style.css:
@-moz-document domain("olx.com.br") {
/* ============================================================
     OLX Brasil runs a Next.js app on its own "olx-ui" component
     library (olx-core-*, olx-adcard, olx-header, olx-dropdown,
     olx-modal, …) — a DIFFERENT frontend from the European OLX
     sites. Colors are literal hex on stable, BEM-style class
     names (no design-token :root vars exposed, no hashed
     classes), so surfaces are flipped structurally from those
     stable component classes.
     ============================================================ */

  :root { color-scheme: dark !important; }

  /* olx-ui paints every `.olx-text` from `color: var(--text-color)`, declared
     once as `:root { --text-color: #1a1d23 }` (its `.dark` counterpart, which
     the site never activates, resolves to #fff). Nothing re-declares it on
     `body`, so remapping the token at the root lifts every `.olx-text` on the
     ad body, modals and auth shell at once. Components that set their own
     `--text-color` (inverted / semantic variants) still win on themselves. */
  :root { --text-color: #c4cdd6 !important; }

  /* ---- Base page ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Soften every default light border into a dark hairline ---- */
  * { border-color: #2d333b !important; }

  /* olx-ui draws the keyboard focus ring as `outline: 2px solid` off the palette's
     near-black — fine on the white page it was designed for, invisible on every
     surface here, so tabbing through the filter rail's checkboxes and radios showed
     no ring at all. Only the COLOUR is remapped: controls the site leaves without an
     outline stay without one, and the ones that already ring in a light tone or in
     the browser's own `outline-style: auto` are unaffected. */
  :focus { outline-color: #c4cdd6 !important; }

  /* `domain("olx.com.br")` also matches OLX's marketing satellites, which are not
     the marketplace app: the Unbounce landing pages (vender / garantia / lp, all
     rooted at `body.lp-pom-body`) and the WordPress "Dicas" blog (`wp-theme-*` on
     the body, also served as seguranca.olx.com.br). Neither loads a single olx-ui
     component, so the only rules that reach them are the base paint, the heading
     ink and the footer block — enough to darken the page while their own white
     panels and near-black copy stay put, which is how the Unbounce FAQ questions
     and the blog's section titles ended up near-white on white. Hand both shells
     back to their native light rendering instead of half-theming them. */
  body.lp-pom-body,
  body[class*="wp-theme-"] {
    background-color: #ffffff !important;
    color: #212529 !important;
  }
  body.lp-pom-body h1, body.lp-pom-body h2, body.lp-pom-body h3,
  body[class*="wp-theme-"] h1, body[class*="wp-theme-"] h2, body[class*="wp-theme-"] h3,
  body.lp-pom-body a:hover,
  body[class*="wp-theme-"] a:hover { color: inherit !important; }
  /* Unbounce only, classless anchors only, and not `!important`. Those pages hand
     their inline "Aqui" / "clique aqui" links no colour at all, so the unqualified
     `a` rule further down paints them the marketplace's near-white on white; every
     other link there is a CTA whose own class rule has to keep winning. The blog
     colours all of its links itself, including classless ones through context
     rules, so the same override would flatten them. */
  body.lp-pom-body a:not([class]) { color: inherit; }
  /* Their forms — the blog's newsletter sign-up and its header search — are the
     other place the marketplace paint lands: dark fields on a white page with the
     field labels lifted to near-white. Submit inputs keep their own brand fill. */
  body.lp-pom-body input:not([type="submit"]):not([type="button"]),
  body.lp-pom-body textarea,
  body.lp-pom-body select,
  body[class*="wp-theme-"] input:not([type="submit"]):not([type="button"]),
  body[class*="wp-theme-"] textarea,
  body[class*="wp-theme-"] select {
    background-color: #ffffff !important;
    color: #212529 !important;
  }
  body.lp-pom-body label, body.lp-pom-body legend,
  body[class*="wp-theme-"] label, body[class*="wp-theme-"] legend {
    color: inherit !important;
  }
  body.lp-pom-body footer,
  body.lp-pom-body [class*="footer"],
  body.lp-pom-body footer a,
  body[class*="wp-theme-"] footer,
  body[class*="wp-theme-"] [class*="footer"],
  body[class*="wp-theme-"] footer a {
    background-color: transparent !important;
    color: inherit !important;
    border-top-width: 0 !important;
  }

  /* ============================================================
     Header / global nav (white bar -> deep neutral dark)
     ============================================================ */
  #header,
  header.olx-header,
  .olx-header,
  .olx-header__main-menu,
  nav.olx-header__main-menu {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  .olx-header a,
  .olx-header button,
  .olx-header__main-menu a { color: #e6edf3 !important; }
  /* Search submit button: a 44px literal-white (#EFF1F5) circle at the end of
     the search pill — under the audit's size floor, so it glares as a bright
     dot in the dark header. Its magnifier is fill="currentColor" but an inner
     span forces a near-black color, so darkening the circle alone would leave
     the glyph dark-on-dark; lift both. The 1x24px `::before` is the light
     hairline divider before it. Its class is hashed, but it is reliably the
     search form's only direct button child. */
  #header form > button {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  #header form > button * { color: #e6edf3 !important; }
  #header form > button:hover { background-color: #2d333b !important; }
  #header form > button::before { background-color: #2d333b !important; }
  /* The three skip links are off-screen until tabbed to, then reveal themselves on
     `--color-neutral-70` (#FFF) — a white slab in the header corner carrying the
     lifted brand purple at ~2.2:1, and the first thing a keyboard user lands on. */
  .olx-header__skip-links:focus {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  /* The narrow-viewport shell opens with a smart-app banner ("Só no app da OLX")
     ABOVE the nav — `div.olx-header__app-banner`, a full-width literal #EFF1F5 strip
     that only exists at mobile widths, so no desktop pass ever saw it and no rule here
     reached it. Natively it is the tinted sibling of the white header; keep that
     relationship inverted by settling it on the elevated tone rather than the header's
     own #0d1117. Its title carries the palette's near-black ink and its description the
     muted #5E6A82 — both dark-on-dark once the strip darkens — and the close X is a
     `fill="currentColor"` glyph off the same #5E6A82, on its own #EFF1F5 button fill.
     The purple app tile and the orange "Baixe" CTA (already `--primary`) are the
     banner's brand identity and stay. */
  .olx-header__app-banner {
    background-color: #1c2128 !important;
    border-bottom: 1px solid #2d333b !important;
  }
  .olx-header__app-banner-close-button { background-color: transparent !important; }
  .olx-header__app-banner-close-icon { color: #c4cdd6 !important; }
  .olx-header__app-banner-title { color: #e6edf3 !important; }
  .olx-header__app-banner-description { color: #9aa6b0 !important; }
  /* Narrow viewports swap the header nav for a FIXED bottom tab bar
     (nav.olx-navbar, literal white). Nothing else in the theme reaches it, so
     its Início/Buscar/Anunciar/Chat/Menu labels — already lifted to near-white
     by the header rules — sat unreadable on white. */
  nav.olx-navbar,
  .olx-navbar {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  /* The tab bar marks the current tab by painting its icon (`svg.olx-navbar--active`)
     AND its label (`span.typo-caption.olx-navbar--active`) the raw OLX purple. Against
     the dark bar that lands at ~2:1 — the ACTIVE tab ends up the dimmest glyph in the
     row, while every inactive one is near-white. Lift it to the readable violet. The
     compound selector is required for the LABEL: the `[class*="typo-caption"]` utility
     rule further down ties this one at 0-1-0 and wins on source order, so the active
     caption rendered the same grey as every inactive one and the "you are here" signal
     survived only on the icon. */
  .olx-navbar--active,
  [class*="typo-"].olx-navbar--active { color: #b794f6 !important; }
  /* Navbar dropdown panels */
  .olx-navbar__dropdown,
  [class*="navbar__dropdown"],
  [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* The bottom tab bar's "Menu" opens a FULL-SCREEN overflow sheet
     (`ul#ds-overflow-menu.olx-header__overflow`) that carries a literal white
     bg and paints its highlighted row #EFF1F5. It has no `role`, so the
     `[role="menu"]` rule above never reached it, and it only exists in the DOM
     at narrow viewports — a desktop-only pass never sees it. */
  #ds-overflow-menu,
  .olx-header__overflow {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .olx-header__overflow-item > a { background-color: transparent !important; }
  .olx-header__overflow-item > a:hover,
  .olx-header__overflow-item > a:focus { background-color: #21262d !important; }

  /* ============================================================
     Auth flow (conta.olx.com.br) — the login/register pages run a
     separate shell with the "focus" header variant and a
     styled-components divider. Both ship literal white surfaces the
     main-site header rules don't reach.
     ============================================================ */
  header.olx-focus-header,
  .olx-focus-header {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  /* "Ou conecte com" divider: an absolutely-positioned label span carries a white
     bg to mask the rule line under it. Both the wrapper's Tailwind margin utilities
     (mb-2/mb-3, mt-5/mt-6) and the hashed sc-* classes churn between redesigns, so
     anchor on the styled-component `color` prop leaked as a DOM attribute — the
     wrapper carries the divider line's #f2f2f2, and this is the login card's only
     white-bg span. Repaint it onto the card surface + lift the label to a readable
     tone. */
  #__next .olx-container--outlined div[color="#f2f2f2"] > span {
    background-color: #1c2128 !important;
    color: #9aa6b0 !important;
  }
  /* Register (/cadastro) renders its form on a white styled-components
     card the main rules don't reach — meanwhile our generic input/label
     rules already darken the fields and lighten the labels, so the copy
     ends up light-on-white. Dark the CSS-module shell + its card panel
     (hashed child) so the whole form coheres. */
  [class*="mainWrapper_mainContainer"] {
    background-color: #14181d !important;
  }
  /* The card panel churns one nesting level between redesigns: it used to be the
     `> div > div` child, but a newer build wraps it in an extra styled-component
     (`sc-*`) so the actual white panel is now `> div > div > div`. Cover both
     depths — the outer wrapper and the real panel share the same tone, so
     painting both is harmless, and a bare `> div > div` leaves the deep panel
     literal white with our lifted light labels ghosting into it. */
  [class*="mainWrapper_mainContainer"] > div > div,
  [class*="mainWrapper_mainContainer"] > div > div > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Its form copy (olx-text variants, radio labels, password-rule hints
     and helper/error captions) all carry near-black hex — dark-on-dark
     now the card is dark. Lift within the auth shell only. */
  [class*="mainWrapper_mainContainer"] .olx-text,
  [class*="mainWrapper_mainContainer"] .olx-radio__content .olx-text {
    color: #c4cdd6 !important;
  }
  [class*="mainWrapper_mainContainer"] .olx-text--body-large,
  [class*="mainWrapper_mainContainer"] .olx-text--body-medium {
    color: #e6edf3 !important;
  }
  [class*="mainWrapper_mainContainer"] .olx-text--caption,
  [class*="mainWrapper_mainContainer"] [id*="text-input-error"] {
    color: #9aa6b0 !important;
  }
  /* Its "ou" divider label is an absolutely-positioned white chip that
     masks the rule line — repaint it onto the card surface. */
  [class*="mainWrapper_mainContainer"] span[class*="typo-body-small"] {
    background-color: #1c2128 !important;
  }
  /* Login (/acesso) card ships a "Preciso de ajuda" footer strip on a
     near-white #f5f6f7 styled-component bg — only 35px tall, so it slips
     under the audit's height floor and glares at the foot of the dark
     card. Its classes are hashed (sc-*), but it's reliably the card's
     last-child footer; only the conta auth app still renders a #__next
     wrapper, so scope there and flatten it onto the card. */
  #__next .olx-container--outlined > div:last-child > div {
    background-color: transparent !important;
  }
  /* The login flow's "Como podemos ajudar?" bottom sheet (Quero reativar minha conta /
     Esqueci a minha senha / Entrar sem senha / Preciso de mais ajuda) is a literal-white
     styled-components panel behind a dark scrim, so our lifted near-white heading ghosts
     straight into it. It is pre-rendered hidden at 0x0, which is why no load-time scan of
     /acesso reports it. Every class on it is a churning `sc-*` hash and its nesting depth
     moves between builds; the only stable hook is the `open` attribute the scrim carries
     while — and only while — the sheet is up, which is also the only moment the panel has
     a size. Anchor there, never on depth alone: a `#__next > div > div:only-child` shape
     also names transparent full-bleed layout containers stacked on the brand purple
     (/tabela-fipe's hero and FAQ bands, ajuda's decorative squares). */
  #__next div[open] > div[class*="sc-"] {
    background-color: #1c2128 !important;
  }
  /* Its close X — the sheet's only exit — is a `path fill="#4A4A4A"` literal in the
     SVG markup, i.e. a dark X drawn for the native WHITE panel. Once the panel goes
     dark it sits at ~1.9:1 and all but disappears; no `color` rule reaches an SVG
     fill. Key on the markup hex (the surrounding `sc-*` classes churn) and scope to
     the auth app, where it is the only element painted that colour. */
  #__next path[fill="#4A4A4A"] { fill: #c4cdd6 !important; }
  /* Its four action buttons ring themselves with a literal #E5E5E5 box-shadow written by
     the styled component (not the DS `--button-border-color-default` token), so neither
     the blanket border softening nor the neutral-variant rule reaches it and each button
     wore a bright white outline. Only the auth app does this; scope there. */
  #__next .olx-core-button--neutral {
    box-shadow: inset 0 0 0 1px #2d333b !important;
  }

  /* ============================================================
     Layout containers / generic surfaces
     #2d333b borders already softened above; flatten white/grey
     wrappers to the base or an elevated surface as appropriate.
     ============================================================ */
  main, section, .olx-container {
    background-color: transparent !important;
  }
  /* Outlined containers (white boxes with a hairline) -> elevated card.
     The coupons page (/cupons) ships the same component under the newer
     un-prefixed `container-outlined` name, so its cards stayed literal white
     while our lifted near-white headings ghosted into them. */
  .olx-container--outlined,
  div[data-ds-component="DS-Container"].olx-container--outlined,
  .container-outlined,
  [class*="CouponCard_wrapper"],
  [class*="CouponContent_wrapper"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Search bar (grey field) -> dark input
     ============================================================ */
  .olx-core-input-element,
  .olx-core-input-textarea-element,
  .olx-text-input__input-field,
  .olx-text-input__input-container,
  input[type="text"], input[type="search"], input[type="number"],
  textarea {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #7d8893 !important; opacity: 1 !important; }
  /* olx-ui draws the OUTLINE of its inputs and native selects with a light
     `box-shadow: 0 0 0 Npx #CFD4DD` ring rather than a border, so the blanket
     border-color softening above cannot reach it and every field on the dark
     page keeps a bright white ring (login e-mail, signup CPF/name, the
     Marca/Modelo filter selects). Repaint the ring itself. */
  .olx-text-input__input-container,
  .olx-core-input-container {
    box-shadow: 0 0 0 1px #2d333b !important;
  }
  /* olx-ui reships the same field as `olx-core-input-textarea-element`, which draws
     its ring from `--input-textarea-box-shadow` on the INPUT itself rather than on a
     container — so the container rule above cannot reach it (neither container class
     renders on the search rail or the header location sheet). Its empty/default state
     rings itself in `--color-neutral-90` (#CFD4DD), a bright white outline around the
     filters rail's Preço Min./Máx. fields, the mobile Filtros sheet and the location
     sheet's search box; the `--filled` state rings itself in `--color-neutral-130`
     (#1A1D23), which vanishes on dark. Remap the two tokens on the element so both
     states keep their relative weight. The typed value is already pinned to #e6edf3 by
     the input rule above, so the -130 remap cannot dim it, and the focus ring
     (`--input-textarea-border-color-selected`) and the success / error rings paint
     from their own tokens and are untouched. */
  .olx-core-input-textarea-element {
    --color-neutral-90: #484f58;
    --color-neutral-130: #6b7681;
  }
  /* Native select dropdowns (filters, sort, location) */
  .olx-dropdown__native,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
    box-shadow: 0 0 0 1px #2d333b !important;
  }
  .olx-dropdown__native option,
  select option { background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* Autocomplete / suggestion panels */
  [class*="autocomplete"] ul,
  [class*="autocomplete__list"],
  [class*="oraculo"] ul {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Each search suggestion is a hashed <button> carrying a literal white bg
     INSIDE the (already darkened) list, so the panel reads as a white sheet;
     the "Você está buscando por" group-heading <li> keeps near-black text and
     goes dark-on-dark. Flatten the rows onto the panel and lift their copy. */
  .olx-autocomplete__list button {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }
  .olx-autocomplete__list button:hover,
  .olx-autocomplete__list button:focus { background-color: #21262d !important; }
  .olx-autocomplete__list li,
  .olx-autocomplete__list li * { color: #c4cdd6 !important; }
  .olx-autocomplete__list button strong,
  .olx-autocomplete__list button p { color: #e6edf3 !important; }
  /* At narrow widths the header does NOT render that inline `olx-autocomplete` panel at
     all: tapping the search pill opens a full-screen search MODAL inside
     `.olx-header__search` — a `[role="dialog"] > [role="document"]` pair on a literal
     white sheet, under an #EFF1F5 strip holding the back arrow and the pill, with every
     suggestion row a white <button> of near-black copy. So the site's single most-used
     mobile interaction opened as a full white page, and a desktop pass never sees it
     because the component only mounts below the breakpoint. Every class on it is a
     churning CSS-modules hash, so anchor on the stable BEM ancestor plus the ARIA roles
     the dialog has to keep. The sheet takes the page base and the strip the header tone,
     mirroring the native white/#EFF1F5 pair. The rows' magnifiers are already lifted by
     the `svg[color="var(--color-neutral-130)"]` rule further down. */
  .olx-header__search [role="dialog"],
  .olx-header__search [role="document"] {
    background-color: #14181d !important;
  }
  .olx-header__search [role="document"] > div:first-child {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #2d333b !important;
  }
  .olx-header__search [role="document"] button {
    background-color: transparent !important;
  }
  .olx-header__search [role="document"] button:hover,
  .olx-header__search [role="document"] button:focus {
    background-color: #21262d !important;
  }
  .olx-header__search [role="document"] div,
  .olx-header__search [role="document"] p,
  .olx-header__search [role="document"] span { color: #c4cdd6 !important; }
  .olx-header__search [role="document"] b,
  .olx-header__search [role="document"] strong { color: #e6edf3 !important; }
  /* olx-core-singleselect — the custom dropdown behind the search-results
     "Tipo de Anúncio" / "Ordenar por" controls (and the header location
     picker). Its trigger ships a literal-white bg but is only 36px tall, so
     it slips under the audit's height floor and glares as a white pill; its
     open menu paints each option with near-black text (#1A1D23) on a
     transparent bg (dark-on-dark) and highlights the selected row with a
     light #EFF1F5 surface. Dark the trigger + menu, lift the option text,
     and settle the selected/hover row onto an elevated dark tone (its
     orange check keeps marking the selection). */
  .olx-core-singleselect__trigger {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  .olx-core-singleselect__value,
  .olx-core-singleselect__trigger-content,
  .olx-core-singleselect__placeholder { color: #e6edf3 !important; }
  .olx-core-singleselect__option-list,
  .olx-core-singleselect__menu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .olx-core-singleselect__option,
  .olx-core-singleselect__option-content { color: #e6edf3 !important; }
  .olx-core-singleselect__option--selected,
  .olx-core-singleselect__option--highlighted,
  .olx-core-singleselect__option:hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  /* The trigger draws its OUTLINE with an inset box-shadow off the neutral scale,
     which no border rule can reach: the empty variant rings itself in
     `--color-neutral-90` (#CFD4DD) and the DISABLED one in `--color-neutral-80`
     (#EFF1F5) — both glare as bright white pills down the filters rail (Marca /
     Modelo, desktop AND the mobile Filtros sheet) — while the `--filled` variant
     rings itself in `--color-neutral-130` (#1A1D23), which vanishes on dark so
     the sort/type controls lose their outline entirely. Remap the tokens on the
     trigger (the focus/open ring paints from the purple selected token and is
     untouched); the value text is already pinned by the rules above, so the -130
     remap cannot dim it. Then restate the disabled state as a flat fill-equals-ring
     chip, the way the site distinguishes it natively. */
  .olx-core-singleselect__trigger {
    --color-neutral-90: #484f58;
    --color-neutral-130: #6b7681;
  }
  .olx-core-singleselect__trigger--disabled {
    background-color: #21262d !important;
    box-shadow: inset 0 0 0 1px #21262d !important;
  }
  /* The chosen option is marked by a tick drawn from the raw brand purple (#6E0AD6),
     ~1.9:1 on the elevated row. The row fill alone cannot carry the state: hover paints
     the same tone, so without a legible tick the open menu shows no current selection.
     The glyph is `fill="currentColor"`, so the colour on the SVG is enough. */
  .olx-core-singleselect__option-check {
    color: #b794f6 !important;
    fill: #b794f6 !important;
  }

  /* ============================================================
     OLX accent (raw #F28000 orange) refined for dark
     ------------------------------------------------------------
     Keep the instantly-recognizable OLX orange identity, but pull
     the lightness up slightly and the saturation down a touch so
     it reads cleanly on the near-black palette without glaring.
     ============================================================ */
  /* `.olx-core-button` is `border: none` and draws its outline with
     `box-shadow: inset 0 0 0 1px var(--button-border-color-default)`, so the
     `border-color` here never paints. The primary variant's ring token is
     `--color-primary-100`, which `body.look-feel` (now the whole site) redefines from
     the OLX orange to the brand PURPLE — so every orange CTA shipped wearing a hard
     #6E0AD6 outline. Natively the ring always equals the fill and is invisible;
     repaint it to match ours, the way the secondary and tertiary variants already do. */
  /* Icons inside a button arrive by two paint routes: most are `fill="currentColor"`
     and follow the `color` below, but olx-ui writes the white token straight into the
     SVG markup (`<svg color="var(--color-neutral-70)">` + `path fill=` the same token)
     for some of them — the filter rail's magnifier stayed white at ~2:1 on the orange.
     The token is remapped per fill, so every later rule that re-tunes this variant's
     background restates it too. */
  .olx-core-button--primary,
  button.olx-core-button--primary,
  a.olx-core-button--primary {
    background-color: #f2901f !important;
    color: #1a1206 !important;
    border-color: #f2901f !important;
    box-shadow: inset 0 0 0 1px #f2901f !important;
    --color-neutral-70: #1a1206;
  }
  /* The ink is restated here because the generic `a:hover { color: #ffffff }` further
     down ties `a.olx-core-button--primary` at 0-1-1 and wins on source order, so the
     ANCHOR form of every orange CTA turned white-on-orange under the pointer. */
  .olx-core-button--primary:hover,
  a.olx-core-button--primary:hover {
    background-color: #ffa436 !important;
    color: #1a1206 !important;
    box-shadow: inset 0 0 0 1px #ffa436 !important;
  }

  /* Secondary button (peach bg / orange text) -> subtle dark-amber.
     `.olx-core-button` is `border: none` and draws its outline with
     `box-shadow: inset 0 0 0 1px var(--button-border-color-default)`, so the
     `border-color` above never paints; the secondary variant's ring token is
     the near-white #FFF3E6, which glared as a bright hairline around every
     Chat / "Exibir telefone" CTA. Repaint the ring itself. */
  .olx-core-button--secondary,
  button.olx-core-button--secondary,
  a.olx-core-button--secondary {
    background-color: #3a2a14 !important;
    color: #f6b35e !important;
    border-color: #5a4220 !important;
    box-shadow: inset 0 0 0 1px #5a4220 !important;
  }
  /* Every `.olx-core-button` variant lifts its fill on hover through
     `--button-background-color-hover` (#FFF -> #EFF1F5 for the neutral-surfaced ones),
     but our variant fills are `!important` with no hover counterpart, so the lift was
     erased and only `--primary` and `--tertiary` — which do carry one — still responded
     to the pointer. Restate the lift for the rest so every button still answers hover.
     Placed before the `--disabled` rule below, which ties these at 0-2-0 and therefore
     wins on source order: a disabled button stays inert. */
  .olx-core-button--secondary:hover,
  button.olx-core-button--secondary:hover,
  a.olx-core-button--secondary:hover { background-color: #4a3519 !important; }
  /* Chips (the /cupons "Categorias" filter) are a white 32px pill — short
     enough to slip the audit's height floor. Every state is token-driven, so
     remap the tokens rather than hardcode each state; that keeps the hover /
     selected / disabled structure intact. The purple accent BORDER on
     hover+selected has to be restated explicitly, because the blanket
     `* { border-color }` reset at the top flattens it. */
  .olx-core-chip {
    --chip-background-color-default: #21262d;
    --chip-border-color-default: #2d333b;
    --chip-font-color-default: #e6edf3;
    --chip-background-color-hover: #2d333b;
    --chip-border-color-hover: #b794f6;
    --chip-font-color-hover: #ffffff;
    --chip-background-color-selected: #2a2440;
    --chip-border-color-selected: #b794f6;
    --chip-font-color-selected: #c9b6f5;
    --chip-background-color-disabled: #1c2128;
    --chip-border-color-disabled: #2d333b;
    --chip-font-color-disabled: #6b7681;
  }
  .olx-core-chip:hover,
  .olx-core-chip[data-selected="true"] { border-color: #b794f6 !important; }

  /* Tertiary = the outline CTA (coupon cards' "Ver produtos"): a white fill
     with orange copy and an orange `box-shadow` ring. The white fill hid on
     the native white card but glares once the card goes dark, and the ring is
     a box-shadow the border softening can't reach. Hollow it out, keep the
     orange identity. */
  .olx-core-button--tertiary,
  a.olx-core-button--tertiary,
  button.olx-core-button--tertiary {
    background-color: transparent !important;
    color: #f6b35e !important;
    box-shadow: inset 0 0 0 1px #f2901f !important;
  }
  .olx-core-button--tertiary:hover { background-color: #3a2a14 !important; }
  /* Neutral / outline buttons (white) -> elevated dark */
  .olx-core-button--neutral,
  button.olx-core-button--neutral {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .olx-core-button--neutral:hover,
  button.olx-core-button--neutral:hover { background-color: #2d333b !important; }
  /* `--link` is the TEXT-only variant (`--button-link-background-color-default:
     transparent`, brand-purple label): pagination numbers, the SEO footer's "Mostrar
     mais", the autos filter rail's "Todas as marcas" jump. Grouping it with `--neutral`
     gave it a filled grey pill, so it read as a button instead of a link — and only the
     ANCHOR form was corrected, leaving every `<button class="…--link">` a grey pill.
     Match the variant itself. `.olx-core-button.olx-core-button--disabled` (0-2-0) still
     wins for pagination's current-page chip. */
  .olx-core-button--link {
    background-color: transparent !important;
    color: #f6b35e !important;
    border-color: transparent !important;
    /* Its hover ring is `--button-border-color-hover` (#F0E6FF) drawn as an inset
       box-shadow — invisible on the native white page, a lavender outline here. */
    box-shadow: none !important;
  }
  .olx-core-button--link:hover { color: #ffc98a !important; }

  /* The auth app and the results view-switcher reuse `--primary` on buttons
     that are NOT orange CTAs, so the blanket primary rule above repaints them:
     the Google/Facebook social logins lose their brand identity and the
     DISABLED submit button looks enabled. Each of these carries an extra
     stable class, so out-specify with a two-class selector (the primary rule
     tops out at `button.olx-core-button--primary`, 0-1-1). */
  .olx-core-button.olx-core-button-social--google {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    box-shadow: inset 0 0 0 1px #2d333b !important;
    --color-neutral-70: #e6edf3;
  }
  /* Facebook keeps its brand blue (#0866FF) with white copy. */
  .olx-core-button.olx-core-button-social--facebook {
    background-color: #0866ff !important;
    color: #ffffff !important;
    box-shadow: inset 0 0 0 1px #0866ff !important;
  }
  /* Disabled/current buttons ship a light #EFF1F5 surface (the auth submit
     before an e-mail is typed, pagination's "Página anterior" and the
     current-page marker) — mapped to the elevated dark tone so the state
     still reads as inactive rather than as an enabled orange CTA. The label
     needs #8b949e, not a dimmer grey: the site reuses `--disabled` for the
     CURRENT PAGE number, which is real information, and #6b7681 on this chip
     lands at 3.2:1. This still reads clearly inactive against the near-white
     copy and the amber page links beside it. */
  .olx-core-button.olx-core-button--disabled {
    background-color: #21262d !important;
    color: #8b949e !important;
    box-shadow: inset 0 0 0 2px #21262d !important;
    --color-neutral-70: #8b949e;
  }
  /* Search-results list/grid switcher: BOTH buttons ship `--primary`, and the
     CURRENT view is marked with `--disabled`. Natively the active one is the
     lavender brand tint (#F0E6FF) and the inactive is white, so the blanket
     primary rule painted both orange and erased the selected state. Restore
     the pair on dark: violet chip for the active view, neutral for the other. */
  [class*="ToggleLayoutButton"] .olx-core-button {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
    box-shadow: none !important;
    --color-neutral-70: #c4cdd6;
  }
  [class*="ToggleLayoutButton"] .olx-core-button.olx-core-button--disabled {
    background-color: #2a2440 !important;
    color: #c9b6f5 !important;
    border-color: #3a3358 !important;
    box-shadow: none !important;
    --color-neutral-70: #c9b6f5;
  }

  /* `.olx-button` is a SECOND button component (the Garantia OLX flow behind the
     ad-page price box — "Solicitar", "Solicitar a garantia da OLX", "Fechar" — and
     its modals), parallel to `.olx-core-button` but drawing a REAL 1px border
     instead of a box-shadow ring. So the blanket `* { border-color }` reset at the
     top flattened each variant's coloured border to grey (a grey hairline around
     the orange Solicitar CTA), and the component was otherwise unthemed: its primary
     shipped raw #F28000 + white copy, out of step with the refined #f2901f dark-copy
     CTAs everywhere else. Re-tune each variant onto the dark palette, mirroring the
     `.olx-core-button` treatment; danger keeps its semantic red. `--disabled` is
     restated last so a `--primary.--disabled` button (0-1-0 tie) reads inactive. */
  .olx-button--primary {
    background-color: #f2901f !important;
    color: #1a1206 !important;
    border-color: #f2901f !important;
  }
  .olx-button--primary:hover {
    background-color: #ffa436 !important;
    color: #1a1206 !important;
    border-color: #ffa436 !important;
  }
  .olx-button--secondary {
    background-color: transparent !important;
    color: #f6b35e !important;
    border-color: #f2901f !important;
  }
  .olx-button--secondary:hover { background-color: #3a2a14 !important; }
  .olx-button--tertiary {
    background-color: #3a2a14 !important;
    color: #f6b35e !important;
    border-color: #5a4220 !important;
  }
  .olx-button--tertiary:hover { background-color: #4a3519 !important; }
  .olx-button--neutral {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .olx-button--neutral:hover { background-color: #2d333b !important; }
  .olx-button--link {
    background-color: transparent !important;
    color: #f6b35e !important;
    border-color: transparent !important;
  }
  .olx-button--link:hover { color: #ffc98a !important; }
  .olx-button--danger {
    background-color: #d93a3a !important;
    color: #ffffff !important;
    border-color: #d93a3a !important;
  }
  .olx-button--danger:hover {
    background-color: #e85454 !important;
    border-color: #e85454 !important;
  }
  /* Restated last, and with its own `:hover`, so a disabled button of any variant reads
     inert: the variant hover rules above are 0-2-0 and would otherwise out-rank the
     0-1-0 base disabled rule and light it up under the pointer. */
  .olx-button--disabled,
  .olx-button--disabled:hover {
    background-color: #21262d !important;
    color: #8b949e !important;
    border-color: #21262d !important;
  }

  /* ============================================================
     Ad / listing cards (home + search, vertical + horizontal)
     ============================================================ */
  .olx-adcard,
  .olx-adcard__vertical,
  .olx-adcard__horizontal,
  section.olx-adcard {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    border-radius: 8px !important;
    color: #c4cdd6 !important;
  }
  /* Image placeholder block inside cards (grey #EFF1F5) */
  .olx-adcard__media,
  picture {
    background-color: #21262d !important;
  }
  /* Home hero carousel progress bar: each 48x4 segment is a literal #CFD4DD
     track (too short for the audit's size floor) that glares as a row of
     bright pills on the dark hero. The FILLED portion is painted by an
     animated orange `::after`, and the state lives on `data-state`, so darken
     only the not-yet-played track and the orange progress stays intact. */
  .olx-core-carousel__progress-item[data-state="current"],
  .olx-core-carousel__progress-item[data-state="next"] {
    background-color: #3a424c !important;
  }

  /* Loading skeletons paint a light shimmer (linear-gradient of
     #eff1f5 -> #cfd4dd) that flashes bright on the dark page during
     every load — swap the gradient for a flat dark placeholder. */
  .olx-core-skeleton,
  [class*="skeleton"] {
    background-image: none !important;
    background-color: #21262d !important;
  }
  /* "Online" seller indicator: a green dot (--color-feedback-success-100)
     wrapped in two animated 9/11px pulse rings painted with the scale's
     LIGHTEST green (#DEF9CC). Invisible against the native white card, they
     glare as a pale halo on dark — and at 11px they sit under the audit's size
     floor. Remap only the ring token on the indicator; the dot keeps its
     green. */
  .olx-adcard__online { --color-feedback-success-80: #1f6b54; }

  /* Card title / price text */
  .olx-adcard__title,
  .olx-adcard a.olx-core-link--main { color: #e6edf3 !important; }
  .olx-adcard__price { color: #ffffff !important; font-weight: 600 !important; }
  .olx-adcard__location,
  .olx-adcard__date,
  .olx-adcard a.olx-core-link--grey { color: #8b949e !important; }
  /* Autos/imoveis vertical cards add a spec row (mileage, colour, bedrooms,
     area) as `.olx-adcard__detail` and a supplementary price line (IPTU,
     condomínio) as `.olx-adcard__price-info`, both painted a native muted
     #5E6A82 that reads ~3:1 dark-on-dark once the card is dark. The
     location/date rule above never reached them, so this real listing metadata
     failed contrast. Lift them (and their spec icons, `fill=currentColor`) to
     the same muted tone. */
  .olx-adcard__detail,
  .olx-adcard__detail *,
  .olx-adcard__price-info,
  .olx-adcard__price-info * { color: #8b949e !important; }
  /* Favourite (heart) toggle — OLX floats it as a 32px circular FAB over the
     card photo on a literal-white bg. At 32px it slips under the audit's size
     floor, so every card glares a bright white dot top-right. Settle the
     circle onto an elevated dark surface; the heart icon (and its filled
     favourited state) stays legible. */
  .olx-adcard__favorite,
  [class*="adcard__favorite"],
  [data-testid="adcard-favorite"] {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }
  /* The card's photo-carousel arrows (revealed on card hover, so a load-time scan never
     sees them) are a 32px disc painted by a `::after` from `var(--color-neutral-70)`
     (#fff) — a bright white FAB floating on the photo right beside the favourite heart
     we already darkened. Its chevron is baked into a `background-image` data URI as a
     literal #1a1d23, so darkening the disc alone would leave the glyph invisible: remap
     the disc + hover tokens AND swap the glyph for a light one. The site's own
     `[data-direction="prev"]::after { transform: rotate(180deg) }` still flips it, so a
     single right-pointing chevron serves both directions. */
  .olx-adcard__carousel--prev-next {
    --color-neutral-70: #21262d;
    --color-neutral-80: #2d333b;
  }
  .olx-adcard__carousel--prev-next::after {
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' fill='none'%3E%3Cpath fill='%23c4cdd6' d='M5.23 13.604a.5.5 0 0 1 0-.707l4.48-4.48-4.48-4.48a.5.5 0 0 1 .707-.707l4.833 4.833a.5.5 0 0 1 0 .707l-4.833 4.833a.5.5 0 0 1-.707 0z'/%3E%3C/svg%3E") !important;
    background-repeat: no-repeat !important;
    background-position: 50% !important;
  }

  /* The heart itself is an SVG painted `fill="var(--color-neutral-70)"` (#fff)
     with `stroke="var(--color-neutral-130)"` (near-black): on the native white
     circle that reads as an OUTLINE heart, but on our dark circle it becomes a
     SOLID WHITE heart, so every card looks already-favourited. Remap the two
     tokens inside the button instead of forcing `fill` — the favourited state
     paints from `--color-secondary-*`, so it keeps its purple untouched. */
  .olx-adcard__favorite,
  [data-testid="adcard-favorite"] {
    --color-neutral-70: #21262d;
    --color-neutral-130: #c4cdd6;
  }

  /* ============================================================
     Public seller profile (/perfil/*) — a third styled-components
     app. Its page shell, footer, avatar disc, "Nível de cadastro"
     accordion and pre-rendered photo modal all ship literal white,
     and its metadata paragraphs carry near-black hex, so the card
     copy went white-on-white and the page bled white around the ad
     grid. None of the main-site component rules reach it.
     ============================================================ */
  #layout-default-profile { background-color: #14181d !important; }
  #container-footer-profile { background-color: #0d1117 !important; }
  #layout-default-profile p { color: #c4cdd6 !important; }
  /* "Entre em contato" phone-reveal: the masked digits are veiled by a
     `linear-gradient(270deg, #fff 15%, transparent 100%)` background-IMAGE on a
     hashed styled-component div — same trick as the ad page's, but this app's
     classes are `sc-*` (not `ad__sc-*`) and the ad-page rule is
     `#price-box-container` scoped, so a white smear sat over the hidden number on
     the dark card. It is the only background-image anywhere under the profile
     shell, so clearing it on the app's styled-components is safe. */
  #layout-default-profile [class*="sc-"] { background-image: none !important; }
  /* …but that veil is also what keeps the digits from colliding with the
     "Exibir telefone" label: the gradient div is an ABSOLUTE overlay sitting on
     the exact box of the number, with the button as its only child, so removing
     the veil renders "41 99103 - ****" and the label in the same 92px, both
     illegible. The overlay itself is unreachable — hashed class, and selecting a
     parent by its child needs the Level-4 parent pseudo-class, which the
     userstyles.org parser strips — so put the veil on the BUTTON instead,
     dark instead of white and hard enough
     to blot the digits under the label while its left edge still fades. Only two
     `--link` buttons exist here and the other ("Compartilhar") already sits on
     this exact card colour, so the gradient is invisible on it. Outspecifies the
     blanket `background-image: none` above (1-1-1 vs 1-1-0). */
  #layout-default-profile button.olx-core-button--link {
    background-image: linear-gradient(270deg, #1c2128 88%, rgba(28, 33, 40, 0) 100%) !important;
  }
  .olx-avatar { background-color: #21262d !important; }
  /* Single-dash `olx-accordion` (distinct from the `olx-core-accordion`
     used by the header's Categorias sheet). */
  .olx-accordion,
  .olx-accordion__button,
  .olx-accordion__content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .olx-accordion__button,
  .olx-accordion__button *,
  .olx-accordion__content * { color: #e6edf3 !important; }
  /* Its registration-level bar fills the achieved tiers from the feedback
     scales and leaves the remaining one on the container's #F5F6F7 — remap
     that token so only the unearned tier darkens. */
  #layout-default-profile [class*="level-"] { --color-neutral-lighter: #3a424c; }
  .olx-image-carousel { background-color: #21262d !important; }
  .olx-modal__topbar,
  .olx-modal__topbar-button,
  [id^="ds-modal-body"] > div {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  /* Its listing tiles use `olx-ad-card` (hyphenated — a different component
     from the `olx-adcard` of home/search), whose spec chips keep near-black
     copy on the now-dark card. */
  .olx-ad-card__labels-item,
  .olx-ad-card__labels-item * { color: #9aa6b0 !important; }

  /* ============================================================
     Badges — keep the semantic hue, settle onto dark
     ------------------------------------------------------------
     TWO badge components ship on olx.com.br: the newer
     `.olx-core-badge` (search results, price box) and the legacy
     `.olx-badge` (the ad page's property-feature pills and the
     "Código do anúncio" chip). Both paint from the SAME token pair
     `--badge-background-color` / `--badge-color`, which each variant
     aliases onto the shared feedback/neutral scales. Remapping those
     scales on the badge elements themselves therefore covers every
     variant of BOTH components at once — including `--neutral`, which
     no class rule of ours reached and shipped as a literal #EFF1F5
     pill with near-black copy. Values follow the design system's own
     (never activated) `.dark` palette so each hue keeps its meaning.
     `--gradient` / `--pro-default` paint from `--color-gradient-*`
     and are deliberately untouched.
     ============================================================ */
  .olx-badge,
  .olx-core-badge {
    --color-neutral-80: #21262d;
    --color-neutral-130: #e6edf3;
    --color-feedback-info-80: #10303a;
    --color-feedback-info-100: #9ce6f9;
    --color-feedback-info-110: #9ce6f9;
    --color-feedback-info-120: #9ce6f9;
    --color-feedback-success-80: #102a23;
    --color-feedback-success-100: #6fd6a8;
    --color-feedback-success-110: #6fd6a8;
    --color-feedback-success-120: #6fd6a8;
    --color-feedback-attention-80: #322a12;
    --color-feedback-attention-100: #e6c463;
    --color-feedback-attention-110: #e6c463;
    --color-feedback-attention-120: #e6c463;
    --color-feedback-error-80: #3a1b16;
    --color-feedback-error-100: #f0a193;
    --color-feedback-error-110: #f0a193;
    --color-feedback-error-120: #f0a193;
    --badge-secondary-background-color: #2a2440;
    --badge-secondary-color: #c9b6f5;
  }
  /* The legacy pills wrap their label in a `.olx-text` / typo utility that the
     text rules further down lift to near-white; with the pill now dark that
     coheres, but pin the label to the badge's own resolved token so a tinted
     variant keeps its hue. */
  .olx-badge > span,
  .olx-core-badge > span { color: inherit !important; }
  /* `.olx-core-badge--info` is the exception to the token remap: BOTH frontends
     hard-set its pair to the lavender brand tint rather than the cyan info
     scale — the listing app writes the literals (#F0E6FF / #6E0AD6) straight
     onto `--badge-*`, and the ad page routes it through the purple `secondary`
     scale. Neither is reachable by remapping the feedback tokens, so keep the
     explicit violet chip here (it is the same chip `--secondary` renders).
     `#adview`'s copy also has to be lifted at the token level, because a hashed
     rule there re-asserts the raw purple; `#reputation-bar` keeps that token. */
  .olx-core-badge--info,
  .olx-core-badge--secondary {
    background-color: #2a2440 !important;
    color: #c9b6f5 !important;
    border-color: #3a3358 !important;
  }
  #adview .olx-core-badge {
    --color-secondary-100: #c9b6f5;
    --color-secondary-110: #c9b6f5;
  }
  /* …and the ad page's "Garantia da OLX" chip escapes BOTH of those: it carries an
     INLINE `background-color: var(--color-secondary-70); color: var(--color-secondary-100)`,
     which the app's own look-feel layer then rewrites through
     `body.look-feel [style*="background-color: var(--color-secondary-70)"] {
     background-color: var(--color-primary-70) !important }` (and the matching `color`
     rule). That is specificity 0-2-1 with `!important`, so the 0-1-0 `--info` rule
     above loses the cascade outright and the chip shipped as a #F0E6FF lavender pill
     with #6E0AD6 copy, wedged between two correctly dark siblings on the same line.
     Beat it at the TOKEN level rather than escalating specificity: the site's rule
     still "wins", but on this element the tokens it substitutes now compute dark.
     Both scales are declared because the rewrite swaps secondary for primary. */
  [class*="badge"][style*="var(--color-secondary-70)"] {
    --color-primary-70: #2a2440;
    --color-secondary-70: #2a2440;
    --color-primary-100: #c9b6f5;
    --color-secondary-100: #c9b6f5;
  }
  /* The boosted "Impulsionado" ad-card badge is `--info` overridden by a
     `bg-primary-100` utility that paints it the OLX orange, distinct from the
     purple `bg-secondary-100` "Destaque". The explicit `--info` violet rule above
     flattened BOTH to the same violet chip, erasing the boosted tier's orange
     identity. Restore the orange (dark copy for contrast on the light orange). */
  .olx-core-badge--info.bg-primary-100,
  .olx-adcard__primary-badge.bg-primary-100 {
    background-color: #f2901f !important;
    color: #1a1206 !important;
    border-color: #f2901f !important;
  }
  /* The promotion badge "Destaque" is the same `--info` component overridden by a
     `bg-secondary-100` utility that paints it SOLID brand purple with white copy — a
     loud flag over the card photo — while the transactional badges beside it
     ("Entrega Fácil", "Parcele sem juros") are the SUBTLE lavender-tint chip with
     purple copy. Both tiers resolved to the one violet chip above, so a promoted
     listing looked exactly like an ordinary one. Restore the solid tier on the same
     lifted violet the coupon action uses; the subtle tier keeps the chip. */
  .olx-core-badge--info.bg-secondary-100,
  .olx-adcard__primary-badge.bg-secondary-100 {
    background-color: #7c3aed !important;
    color: #ffffff !important;
    border-color: #7c3aed !important;
  }
  /* The autos "Histórico Veicular" trust badge (aria-label "Anúncio com histórico
     veicular") is an `--secondary` badge the site paints GREEN via an inline
     `background: var(--color-feedback-success-100)`. The explicit violet `--secondary`
     rule above (0-1-0) out-ranks the inline bg and flattened it to the SAME purple
     chip as "Destaque" — erasing the green vehicle-history trust signal and making
     the two distinct badge meanings look identical. Restore a readable dark-mode
     green; the inline-style hook reaches 0-2-0 to win over the violet rule. */
  .olx-core-badge--secondary[style*="feedback-success"] {
    background-color: #1f7a4d !important;
    color: #ffffff !important;
    border-color: #1f7a4d !important;
  }
  /* Same trap, `--info` side: the ad-card "Frete grátis" badge inlines
     `--badge-background-color: var(--color-feedback-success-80)` /
     `--badge-color: var(--color-feedback-success-120)`, i.e. the SUBTLE green pair the
     token block above already remaps. The explicit violet `--info` rule (0-1-0) beat
     that token path, so free shipping rendered as the exact same chip as the natively
     purple "Entrega Fácil" / "Parcele sem juros" sitting beside it on the same card —
     three badges, one look, one meaning left. Restate the success pair through the
     same inline-style hook (0-2-0). `audit-chroma` cannot see this: green -> violet is
     a hue swap between two chromatic colours, not a flattening to grey. */
  .olx-core-badge--info[style*="feedback-success"] {
    background-color: #102a23 !important;
    color: #6fd6a8 !important;
    border-color: #1d4a3c !important;
  }

  /* ============================================================
     Search-results page: filters sidebar + form controls
     ============================================================ */
  [data-testid="filter-box-clodoview"],
  [data-testid*="filter"],
  [class*="filter-box"],
  label {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  [data-testid="filter-box-clodoview"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    border-radius: 8px !important;
  }
  /* The "Benefícios da Garantia OLX" chips are CSS-module <label>s toggled by a
     preceding hidden checkbox. Natively the unselected chip is a white pill and
     the SELECTED one is the lavender brand tint (#F0E6FF) with deep-purple copy
     and border — but the blanket `label { background-color: transparent; color }`
     rule above flattened both states to the same borderless dark chip, so a
     selected filter looked exactly like an unselected one. Restore the pair.
     OLX migrated these CSS-module class names from `Chips_chipContent__hash` to
     `Chips-module-scss-module__hash__chipLabel`, so the old substring matched
     nothing and both states regressed to flat grey; target the stable `chipLabel`
     element name (unique to these chips — ButtonChips has no `chipLabel`) so the
     rule survives either build. */
  [class*="Chips_chipContent"] label,
  label[class*="chipLabel"] {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  [class*="Chips_chipContent"] input:checked + label,
  input:checked + label[class*="chipLabel"] {
    background-color: #2a2440 !important;
    color: #c9b6f5 !important;
    border-color: #b794f6 !important;
  }
  /* Each chip label wraps its text in an inner `<p class="typo-body-small">`; the
     generic typo rule further down matches that <p> directly and beats the label's
     inherited colour, so the SELECTED chip's violet tint (and the unselected chip's
     lifted grey) never reached the text — every chip read the same flat grey. Let
     the <p> inherit the label colour so the selected state keeps its accent. */
  [class*="Chips_chipContent"] label p,
  label[class*="chipLabel"] p { color: inherit !important; }

  /* Narrow viewports replace the filters rail with a sticky "Filtros" bar whose
     CSS-module wrapper ships a literal white surface, and whose chips paint on
     an inner `ButtonChips_chipContent` span (white; the CHECKED category chip is
     the lavender brand tint with deep-purple copy). The button itself is
     transparent, so a rule on the button never paints. */
  /* Same CSS-module rename as the garantia chips: `ListingPage_mobileFiltersWrapper`
     and `ButtonChips_*` became `…-module-scss-module__hash__mobileFiltersWrapper` /
     `__chipContent` / `__checked`, so the old substrings matched nothing — the whole
     bar reverted to a literal white band and the CHECKED category chip to its raw
     lavender tint. Match the stable element names (compound with the component so
     the generic `checked`/`chipContent` names can't over-reach). */
  [class*="ListingPage_mobileFiltersWrapper"],
  [class*="mobileFiltersWrapper"] {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  [class*="ButtonChips_chipContent"],
  [class*="ButtonChips"][class*="chipContent"] {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  [class*="ButtonChips_checked"],
  [class*="ButtonChips"][class*="checked"] {
    background-color: #2a2440 !important;
    color: #c9b6f5 !important;
    border-color: #b794f6 !important;
  }
  /* Its header collapses to the fluid location picker, whose label span keeps a
     near-black hex and goes dark-on-dark against the darkened bar. */
  .olx-header__location-fluid button,
  .olx-header__location-fluid button * { color: #e6edf3 !important; }

  /* Subcategory-header icon tile: a small (~36px) rounded #EFF1F5 chip
     holding the category glyph — under the audit's size floor, so it
     slips past as a bright square glaring in the dark filters rail.
     Settle onto the elevated media tone; the colored glyph stays legible. */
  [class*="SubcategoryFilterHeader_icon"],
  [class*="SubcategoryFilterHeader"][class*="icon"] {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Category-less listings (state landing / broad search / the redirect a bad URL
     lands on) render the filters rail as a `RootCategoriesListDesktop` list whose
     every root-category link is a `ParentCategoryLink_container` pill shipping a
     literal #EFF1F5 surface — 30+ bright white pills down the dark rail. The
     hashed CSS-module suffix churns, so match on the substring. Its colored 3D
     category icon and the grey `--grey` label stay legible on the elevated tone.
     The `ParentCategoryLink_container__hash` name migrated to
     `…-module-scss-module__hash__container`, so match the component + `container`. */
  [class*="ParentCategoryLink_container"],
  [class*="ParentCategoryLink"][class*="container"] {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Filter form controls (checkboxes / radios) — olx-ui paints the box
     itself on a `::before` pseudo (element bg is transparent), so the
     element-bg audit is blind to it: every UNCHECKED box renders a
     glaring literal-white square/circle down the filters rail. Settle
     the empty box onto an elevated dark surface with a light-grey
     hairline so it reads as an outline, and keep the CHECKED state on
     the brand OLX purple (#6E0AD6) with its white tick intact. */
  /* Each checkbox/radio row is a <label> with `border: 1px solid #fff` — a
     deliberately invisible border on the native white page. The blanket
     border-color softening at the top repaints it #2d333b, drawing a visible
     box around every filter label. Put it back to invisible. */
  .olx-core-checkbox-radio__root {
    border-color: transparent !important;
  }
  .olx-core-checkbox-radio__input::before {
    background-color: #1c2128 !important;
    border-color: #6b7681 !important;
  }
  .olx-core-checkbox-radio__input:checked::before {
    background-color: #6e0ad6 !important;
    border-color: #6e0ad6 !important;
  }
  /* Toggle switch (e.g. "Anunciantes bem avaliados") ships a light-grey
     #cfd4dd OFF track that glares on dark; darken only the unchecked
     track (scope with :not(:checked)) so the native ON accent + white
     knob are untouched. */
  .olx-core-toggle-switch:not(:checked) {
    background-color: #484f58 !important;
  }

  /* Advertising placeholders (white/grey ad slots) -> blend into base.
     Attribute substring matching is case-sensitive, so cover both the
     lower-case slot classes and the hashed React `AdvertisingAnchor`
     (sticky bottom ad) container, whose light-grey panel leaks. */
  [data-testid="advertising-placeholder"],
  [class*="advertising"],
  [class*="Advertising"],
  [class*="anchor-container"] {
    background-color: #14181d !important;
  }

  /* Breadcrumbs */
  [data-ds-component="DS-Breadcrumb"],
  [data-ds-component="DS-Breadcrumb"] *,
  .olx-breadcrumb a,
  nav[aria-label*="readcrumb"] a { color: #9aa6b0 !important; }
  [data-ds-component="DS-Breadcrumb"] a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Individual ad / item page
     ------------------------------------------------------------
     The ad detail content lives under the stable #adview wrapper.
     Its cards (price box, seller, safety tips) are styled-component
     wrappers (ad__sc-* hashed names) carrying literal #FFF. Flatten
     all of those to transparent so the dark base shows through, then
     re-elevate the few stable, distinct cards.
     ============================================================ */
  #adview { background-color: #14181d !important; }
  /* Skip elements that carry an inline `background-color: rgb(...)` — on styled
     components that is only ever a DYNAMIC brand/status colour (the share sheet's
     Facebook/Whatsapp/X/copy discs), never a static surface (those come from the
     component's generated class CSS). Neutralizing them to transparent left the
     white share glyphs floating with no coloured disc behind them. */
  #adview [class*="ad__sc-"]:not([style*="rgb("]) {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* The seller "online" indicator is an 8px empty `ad__sc` span painted green from
     its component class (no inline style, so the exclusion above cannot spare it);
     the neutralizer blanked it. It is the ad page's only empty `ad__sc` span, so
     restore its status green. */
  #adview span[class*="ad__sc-"]:empty {
    background-color: #24a148 !important;
  }
  /* …the neutralizer is scoped `#adview [class*="ad__sc-"]` (specificity
     1-1-0), and OLX hangs its hashed styled-component class on the CTA buttons
     themselves (`olx-core-button--primary ad__sc-y9u3u-1`). So it out-specified
     the 0-1-1 button rules and erased their fill: "Enviar mensagem" rendered as
     near-black brown text on the page base inside an orange ring, and Chat /
     "Exibir telefone" lost their amber fill — in the price box AND in the fixed
     top bar. Restate each variant from #adview.
     A tag qualifier alone reaches only 1-1-1, which was enough until the neutralizer
     gained `:not([style*="rgb("])` and rose to 1-2-0 — after which these restores LOST
     again and the two CTAs that currently carry a hashed `ad__sc-` class ("Chat" and
     "Acessar perfil do anunciante") rendered as unfilled outlines in the price box.
     Adding the component's own base class takes each restore to 1-2-1, which out-ranks
     the neutralizer without depending on the shape of an inline style the way a
     repeated `:not()` would. */
  #adview button.olx-core-button.olx-core-button--primary,
  #adview a.olx-core-button.olx-core-button--primary {
    background-color: #f2901f !important;
    color: #1a1206 !important;
    box-shadow: inset 0 0 0 1px #f2901f !important;
  }
  #adview button.olx-core-button.olx-core-button--primary:hover,
  #adview a.olx-core-button.olx-core-button--primary:hover {
    background-color: #ffa436 !important;
    box-shadow: inset 0 0 0 1px #ffa436 !important;
  }
  #adview button.olx-core-button.olx-core-button--secondary,
  #adview a.olx-core-button.olx-core-button--secondary {
    background-color: #3a2a14 !important;
    color: #f6b35e !important;
    box-shadow: inset 0 0 0 1px #5a4220 !important;
  }
  #adview button.olx-core-button.olx-core-button--secondary:hover,
  #adview a.olx-core-button.olx-core-button--secondary:hover {
    background-color: #4a3519 !important;
  }
  #adview button.olx-core-button.olx-core-button--neutral,
  #adview a.olx-core-button.olx-core-button--neutral {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  #adview button.olx-core-button.olx-core-button--neutral:hover,
  #adview a.olx-core-button.olx-core-button--neutral:hover {
    background-color: #2d333b !important;
  }
  #adview button.olx-core-button.olx-core-button--tertiary,
  #adview a.olx-core-button.olx-core-button--tertiary {
    background-color: transparent !important;
    color: #f6b35e !important;
    box-shadow: inset 0 0 0 1px #f2901f !important;
  }
  #adview button.olx-core-button.olx-core-button--tertiary:hover,
  #adview a.olx-core-button.olx-core-button--tertiary:hover {
    background-color: #3a2a14 !important;
  }

  /* `olx-icon-action` (the ad page's favourite / share controls and the photo
     lightbox's Anterior/Próxima arrows) paints its glyph with
     `fill="var(--color-neutral-130)"` — the palette's near-black. On the dark
     page the heart and share icons all but vanished. The lightbox arrows add a
     literal-white disc from a hashed styled-component's `--background-color`
     (40px, so under the audit's size floor). Remap the two tokens on the
     control; the arrows' `aria-label`s are the only stable hook for the disc. */
  .olx-icon-action { --color-neutral-130: #c4cdd6; }
  .olx-icon-action:hover { --color-neutral-130: #e6edf3; }
  /* The lightbox arrows carry an INLINE `--background-color: var(--color-neutral-70)`
     on their icon wrapper, so only remapping that token reaches the disc. Their
     chevron is `fill="currentColor"` with no colour declared — natively the UA's
     black `buttontext`, which `color-scheme: dark` flips to WHITE, painting a
     white chevron onto the white disc. Pin the colour explicitly. */
  button[aria-label="Anterior"],
  button[aria-label="Próxima"] {
    --color-neutral-70: #21262d;
    color: #e6edf3 !important;
  }
  /* Same inline hook, everywhere else the component ships a disc: at narrow
     viewports the ad page floats its favourite + share pair over the photo header
     as 40px `--background-color: var(--color-neutral-70)` circles, i.e. literal
     white — and the `--color-neutral-130` lift above then puts a #c4cdd6 glyph on
     that white at ~1.9:1, so both controls read as blank discs. Remapping the token
     on any wrapper carrying the inline var covers the pair (and any future disc
     placement) without touching the disc-less desktop icon actions, which never
     declare it. */
  .olx-icon-action__icon-wrapper[style*="--background-color"] {
    --color-neutral-70: #21262d;
  }

  /* …and it blanks the photo LIGHTBOX's backdrop: the expanded gallery is a
     fixed, full-viewport `section` whose only class is the hashed
     styled-component, carrying an opaque #EFF1F5 sheet. Flattened to
     transparent, the photo floats over the live ad page — the price box, cards
     and the thumbnail strip all bleed through behind it. It is the ad page's
     ONLY `section[class*="ad__sc-"]` (every other section there is an
     `olx-adcard`), so re-establish an opaque photo-viewer backdrop from that.
     The neutralizer above carries `:not([style*="rgb("])` (specificity 1-2-0),
     so this restore must repeat that `:not()` to reach 1-2-1 and win — a bare
     `section[class*="ad__sc-"]` (1-1-1) loses to it and the backdrop reverts to
     transparent, bleeding the live ad page through the open photo. */
  #adview section[class*="ad__sc-"]:not([style*="rgb("]) {
    background-color: #0d1117 !important;
  }
  /* The gallery was rebuilt as the `advc-slide-show` component, so its root no
     longer carries a hashed `ad__sc-` class and the restore above cannot reach it.
     It is still a `<section>`, which means the generic `main, section` neutralizer
     near the top of the file blanks its natively opaque #EFF1F5 sheet — the open
     photo floats over the live ad page again. A single class (0-1-0) out-ranks the
     bare `section` (0-0-1) that blanks it, so match the component itself and stay
     tag-agnostic in case the element type churns. */
  .advc-slide-show__root {
    background-color: #0d1117 !important;
  }
  /* …but that neutralizer also blanks the ad page's FIXED top bar (the
     Fotos/Descrição/Detalhes tabs + Comprar/Chat actions), which ships a
     literal white bg — content then scrolls straight through it. It is
     #adview's own fixed child; re-establish an opaque surface. The `:not()` has to be
     repeated here for the same reason the lightbox restore repeats it: the neutralizer
     is 1-2-0, so a bare `#adview > div[class*="anz3cs"]` (1-1-1) LOSES and the bar goes
     transparent again — the ad photos, the price and the verified-badge list all scroll
     visibly through the tab strip. */
  #adview > div[class*="anz3cs"]:not([style*="rgb("]) {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #2d333b !important;
  }
  /* Narrow viewports do not render that top bar at all — they get a FIXED BOTTOM action
     bar instead (the Solicitar / Chat pair plus an ad slot), another opaque-white
     `ad__sc-` child of #adview that the neutralizer blanks, so the listing photos and
     section headings scrolled visibly through and between the two CTAs. Same shape as
     the top-bar restore, including the repeated `:not()` needed to out-rank the 1-2-0
     neutralizer. The bar's own hook is the styled-component id, which churns on a
     rebuild; `#sticky-footer-buyer-actions` is the stable id of the button row inside
     it, painted the same tone so a hash churn degrades to an opaque button band rather
     than back to floating controls over live content. */
  #adview > div[class*="1bi6ic6"]:not([style*="rgb("]),
  #adview #sticky-footer-buyer-actions {
    background-color: #0d1117 !important;
  }
  #adview > div[class*="1bi6ic6"]:not([style*="rgb("]) {
    border-top: 1px solid #2d333b !important;
  }
  /* The masked phone number is faded out by a `linear-gradient(270deg, #fff …)`
     background-IMAGE strip — a bg-color neutralizer leaves it, so a white smear
     sits over the hidden digits. It is the only gradient inside the price box
     (the seller avatar's url() lives outside it), so clearing background-image
     there is safe. */
  #price-box-container [class*="ad__sc-"] {
    background-image: none !important;
  }
  /* Price box + gallery surrounds (stable ids) -> elevated card */
  #price-box-container,
  [class*="price-box"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* The `gallery` substring is scoped to the ad view on purpose: the home page names
     its sponsored-ads strip `home-premium-gallery`, and an unscoped match painted that
     whole section a tone DARKER than the page base, banding a surface the site leaves
     bare. */
  #item-gallery-image,
  button#item-gallery-image,
  #adview [class*="gallery"] {
    background-color: #0d1117 !important;
  }
  /* Title + price */
  h1, h2, h3 { color: #e6edf3 !important; }
  /* `/mapa-do-site` and its per-category sub-routes open on a Banner section the
     site tints `--color-neutral-80`, with the palette's near-black for both the
     page title and the strapline. `main, section, .olx-container` clears the tint
     and nothing lifts that copy, so a 48px page title sat at 1.06:1. `Banner_` is
     this route family's own component — no other page type carries the prefix. */
  [class*="Banner_container"] { background-color: #1c2128 !important; }
  [class*="Banner_title"] { color: #e6edf3 !important; }
  [class*="Banner_subtitle"] { color: #9aa6b0 !important; }
  /* `/tabela-fipe` is a separate `#__next` route whose section headings and
     feature copy come off `--color-neutral-120` (#3C4453) — an ink meant for the
     white page it was drawn on, ~1.7:1 here. styled-components keeps the component
     name in the class and churns only the trailing hash, so match the prefix. */
  #__next [class*="styles__TitleMedium"],
  #__next [class*="styles__Title-"] { color: #e6edf3 !important; }
  #__next [class*="styles__DiscoverItemText"] { color: #9aa6b0 !important; }
  /* The glyph beside each of those lines is a monochrome path with no fill
     attribute, so it renders UA black rather than following the host colour. */
  #__next [class*="styles__DiscoverIcon"] path { fill: #8b949e !important; }
  /* The two surfaces the route paints for itself, both drawn for a white page: the
     vehicle-picker card is literal white, and the AI-search callout above the results
     is the lavender brand tint (#F0E6FF) carrying the same #3C4453 copy. Everything
     else here is a transparent layout container over the brand-purple hero and FAQ
     bands, so these have to be named one by one rather than swept by depth. */
  #__next [class*="DislocatedContainer"] { background-color: #1c2128 !important; }
  #__next [class*="AiCtaBody"] { background-color: #2a2440 !important; }
  #__next [class*="AiCtaText"] { color: #c4cdd6 !important; }
  /* Its per-vehicle sub-routes (/tabela-fipe/carros, /motos, /caminhoes) add three more
     surfaces of their own. The breadcrumb strip is an olx-ui `nav` tinted
     `--color-neutral-90`; only this route hangs one straight off `#__next`, everywhere
     else the component sits deeper and is transparent, so keep the child combinator. */
  #__next > nav.olx-breadcrumb { background-color: transparent !important; }
  /* The "Modelos mais buscados" tiles are literal-white cards holding a cut-out PNG of
     the car, with the model name in the same #3C4453 page ink. */
  #__next [class*="styles__Card-"] { background-color: #1c2128 !important; }
  #__next [class*="styles__ModelTitle"] { color: #e6edf3 !important; }
  #__next [class*="styles__BrandTitle"] { color: #9aa6b0 !important; }
  /* Section headings and the brand-tile captions are the route's remaining
     white-page inks (#3C4453 and the near-black #1A1D23). */
  #__next [class*="styles__SectionTitle"],
  #__next [class*="BrandsListTitle"] { color: #e6edf3 !important; }
  #__next [class*="BrandName"] { color: #c4cdd6 !important; }
  [class*="price"] strong,
  [class*="price-box"] h2 { color: #ffffff !important; }

  /* OLX "secondary" (purple) design tokens used as RAW vars via inline
     styles in the ad body — e.g. the price-box discount-coupon banner
     paints `background: var(--color-secondary-70)` (light lavender)
     with `--color-secondary-120/130` dark-purple copy on top. The
     class-based secondary overrides can't reach inline-var usage, so
     flip the scale at the token level within #adview: light surface
     token -> dark violet chip, deep text shades -> a readable violet. */
  #adview {
    --color-secondary-70: #2a2440 !important;
    --color-secondary-120: #c9b6f5 !important;
    --color-secondary-130: #c9b6f5 !important;
    /* The price-box discount-coupon banner ("R$ 30 OFF / OFF30") paints
       `background: var(--coupon-bg-color, var(--color-secondary-70))`. The site now
       DEFINES `--coupon-bg-color` (the lavender #F0E6FF tint), so the
       `--color-secondary-70` fallback above never resolves and the banner glared as
       a bright lavender panel in the dark price box. Remap the coupon token itself
       to the same dark violet chip. Its copy paints from
       `var(--coupon-text-color, var(--color-secondary-120))` — the site defines the
       deep-purple #49078F on `--coupon-text-color`, so the secondary-120 fallback
       (lifted above) never resolves and the text went deep-purple-on-dark-violet.
       Remap the coupon text token itself to the readable light violet. */
    --coupon-bg-color: #2a2440 !important;
    --coupon-text-color: #c9b6f5 !important;
    /* Third token of the same set: the banner's "Copiar" action paints
       `background-color: var(--coupon-button-color, var(--color-secondary-100))`, and
       the site defines it as the raw brand purple #6E0AD6. Natively that is a dark
       button on the lavender banner; against the dark chip above it inverts into the
       loudest, most saturated block on the page while every other violet here is
       refined. Lift it the same way, keeping the hue. */
    --coupon-button-color: #7c3aed !important;
  }
  /* The price box's action links ("Simular empréstimo", "Mais opções de parcelamento")
     put their glyph in an inline `<path fill="var(--color-secondary-100)">` — the raw
     brand purple, ~2.3:1 on the dark card, while the label right beside it is already
     lifted to the readable violet. Remap the token on the link so ONLY its own icon
     lifts: the same token feeds the ad page's `--spots-*` illustrations (the location
     building, the account-level spot), whose hues must stay. */
  #adview a.olx-link--main,
  #adview a.olx-core-link--main { --color-secondary-100: #b794f6; }
  /* Seller "Nível de conta" medal — a two-layer SVG whose body paints
     `var(--color-secondary-70)` and whose outline `var(--color-secondary-100)`. The
     `#adview` secondary flip below exists for the coupon banner's lavender SURFACE, and
     it drags the medal's body down to the dark chip tone, so the level marker all but
     vanishes against the purple bar it sits on. Put the lavender back on the medal only;
     the label is ASCII-matched so the accented í can't break the selector. */
  #adview button[aria-label*="vel do vendedor"] {
    --color-secondary-70: #c9b6f5 !important;
    --color-secondary-100: #7c3aed !important;
  }

  /* Seller rating strip: a single 96x27 SVG of five stars, each an EMPTY star
     painted with the literal light-grey #CFD4DD (`--color-neutral-90`). On the
     native white card that is a faint "no rating yet" ghost; on the dark card it
     renders as five BRIGHT, apparently FILLED stars sitting directly above the
     line "Este anunciante ainda não possui avaliações" — the page states a
     five-star rating and no ratings at the same time. A FILLED star is orange
     (verified on a rated seller's profile), so keying on the literal grey hex
     touches only the empty state, and the hex is written into the markup so it
     survives the hashed `ad__sc-*` churn. Settle them onto the same unfilled
     tone the reputation bar and carousel track already use. Scoped to the two
     shells that render seller ratings so no other grey glyph is caught. */
  #adview path[fill="#CFD4DD"],
  #layout-default-profile path[fill="#CFD4DD"] {
    fill: #3a424c !important;
  }
  /* Same lie, other mechanism: the /perfil/ app's star widget paints each star
     with a two-stop gradient — `--color-feedback-attention-100` (orange) up to the
     fill fraction, then that same `--color-neutral-90` #CFD4DD for the remainder —
     so a PARTIAL rating (3.5 of 5) leaves near-white star bodies that read as
     filled, brighter than the orange ones beside them. The rule above cannot reach
     them: the path's `fill` is `url(#…key-…)`, and the grey lives in a `<stop>`.
     The stop writes the token name literally into its markup, so match that string
     — only the unfilled tone uses it and the filled fraction is a different token,
     so the orange is untouched. */
  stop[stop-color="var(--color-neutral-90)"] {
    stop-color: #3a424c !important;
  }

  /* The default seller avatar ships as TWO rasters, one per app. The main site
     serves `static.olx.com.br/…/images/avatar.svg` — a #F5F5F5 square carrying a
     grey figure — as the ~72px disc on the ad page's seller card. The /perfil/
     Next app serves its OWN `…/_next/static/media/avatar.<buildhash>.png`, a
     near-white (#FAFAFA disc, #D5DEE1 figure) circle, through the optimiser at
     `/perfil/_next/image?url=<percent-encoded>` — once per review card plus the
     seller card, so a profile carries five-plus of them. Every seller without a
     photo therefore wears a near-white disc on a dark card, the brightest thing
     on the page. No scanner reaches it: it is image PIXELS, so the element-bg
     walk reads the (transparent) wrapper and `svgWhiteFills` never sees inside an
     `<img>`. The artwork is achromatic, so inverting reproduces the native
     placeholder in reverse (dark disc, legible grey figure) rather than erasing
     anything; `brightness` lifts the inverted near-white off pure black so the
     disc still reads as a disc.
     Every hook ends at the `avatar.` DOT, before the extension and before the
     Next build hash — the hash churns on every deploy, and a real seller PHOTO
     (thumbs/graph.facebook/googleusercontent, none of which contain `avatar.`)
     stays untouched, which is the whole point of not filtering `img` broadly.
     The `%2F` forms cover the optimiser's percent-encoded url= parameter; both
     letter cases are listed because attribute matching is case-sensitive. */
  img[src*="/avatar."],
  img[src*="%2Favatar."],
  img[src*="%2favatar."] {
    filter: grayscale(1) invert(1) brightness(2.2);
  }
  /* Same family, opposite polarity: when a Facebook-sourced photo is missing the
     /perfil/ app falls back to `…/static/media/facebook-default-picture.<hash>.jpeg`,
     a #D3D6DB tile with a WHITE silhouette — light enough to leak the same way, but
     its figure is LIGHTER than its background, so the invert above would leave a
     black silhouette on a mid-grey tile. Darken in place instead: brightness then
     contrast maps the native 214-255 range onto a ~#212121 tile with a ~#8c8c8c
     figure, keeping the silhouette the lighter of the two. */
  img[src*="/facebook-default-picture."],
  img[src*="%2Ffacebook-default-picture."],
  img[src*="%2ffacebook-default-picture."] {
    filter: grayscale(1) brightness(0.51) contrast(5.12);
  }
  /* An ad with no photo renders the site's ONE shared listing placeholder,
     `static.olx.com.br/cd/listing/notFound.png`, as the whole 249x180 card media —
     `olx-image-carousel` pushes it in whenever the photo list is empty, so an SRP,
     a home rail, a "Também podem te interessar" strip or a /perfil/ grid can each
     carry several. The file is fully OPAQUE and entirely light grey (a #DEDEDE plate
     under a #EBEBEB category-glyph pattern; no pixel darker than 220), so the dark
     background `.olx-adcard__media` / `picture` already carries sits behind it and
     corrects nothing.
     Darken in place instead of inverting: the glyphs are LIGHTER than the plate, so
     an invert flips the pattern into dark holes. `brightness` then `contrast` maps
     the 220-236 source range onto a #1f1f1f plate (just under the #21262d card) with
     a #363636 pattern, keeping the native polarity. Keyed on the filename before the
     extension so a format swap survives; the `%2F` forms cover Next's
     `/_next/image?url=` optimiser, both cases because attribute matching is
     case-sensitive. */
  img[src*="/notFound."],
  img[src*="%2FnotFound."],
  img[src*="%2fnotFound."] {
    filter: grayscale(1) brightness(0.46) contrast(3.81);
  }
  /* Same family, dark ink: a seller/store with no picture gets
     `static.olx.com.br/upr/img/photo-off.png` in the 80px `.olx-avatar` disc. The
     file is 95% transparent with #4A4A4A linework, so there is no plate to darken —
     on the disc's #21262d the glyph sits at 1.7:1 and the avatar reads as empty.
     Inverting lands the ink at #929292 (4.9:1). The disc is transparent in the file,
     so it comes from the `.olx-avatar` background — and a `filter` applies to
     everything the element paints, its own background included, which would turn
     #21262d into a near-white plate. The background declared here is therefore the
     PRE-IMAGE of the disc tone under this exact chain: (255 - 0xD6/0xD0/0xC7) * 0.8
     lands back on #21262d. Both halves move together — retune one and the other must
     be recomputed. The `%2F` forms cover the /perfil/ app, which requests the SAME
     file through `/_next/image?url=`. */
  img[src*="/photo-off."],
  img[src*="%2Fphoto-off."],
  img[src*="%2fphoto-off."] {
    background-color: #d6d0c7 !important;
    filter: invert(1) brightness(0.8);
  }

  /* Seller reputation bar: four 70x8 segments whose colours come from INLINE
     `background-color: var(--color-*)`, so no class rule can reach them. The
     achieved tiers use --color-secondary-80/-100 (the purples, keep them) and
     the not-yet-reached tier uses --color-neutral-80 (#EFF1F5), which glares
     as a white bar. Remap only that token, scoped to the bar. */
  #reputation-bar {
    --color-neutral-80: #3a424c !important;
  }

  /* The "ver número" phone-reveal control OLX auto-generates inside the
     ad description is a hashed styled-component span carrying the raw
     saturated OLX purple (#6E0AD6) on BOTH color and -webkit-text-fill,
     so it reads dark-on-dark. Target its stable data-element hook (the
     hashed class churns) and lift to the readable violet. */
  #adview [data-element="button_show-phone"] {
    color: #b794f6 !important;
    -webkit-text-fill-color: #b794f6 !important;
  }

  /* ============================================================
     Text utilities — olx-ui ships Tailwind-style text-color and
     typography classes carrying literal near-black hex; on dark
     they read as black-on-dark. Lift them to the readable scale
     while keeping the dark/secondary hierarchy.
     ============================================================ */
  .text-neutral-130, .text-neutral-120, .text-neutral-130 *,
  [class*="typo-title"], [class*="typo-body-large"],
  [class*="typo-body-medium"] {
    color: #e6edf3 !important;
  }
  .text-neutral-110, .text-neutral-100, .text-neutral-90,
  [class*="typo-body-small"], [class*="typo-caption"],
  [class*="typo-overline"] {
    color: #9aa6b0 !important;
  }
  /* `text-neutral-70` is olx-ui's WHITE-text utility, reserved for copy that sits on a
     coloured brand surface — the mobile listing's "Veja anúncios com Entrega" banner
     paints it on `bg-secondary-100` (#6E0AD6). The typo-scale rules above match those
     same elements on their `typo-body-small` / `typo-caption` class and greyed the copy
     to #9aa6b0, which is 3.2:1 on that purple. The compound selector out-specifies the
     typo rules rather than relying on source order — and it must stay compound: the
     ad-card "Destaque" badge carries `text-neutral-70` too (it is white on the native
     purple chip) but no `typo-*` class, so a bare `.text-neutral-70` would beat the
     badge rules on source order and repaint that copy white, losing the violet the
     dark chip is built around. */
  [class*="typo-"].text-neutral-70 { color: #ffffff !important; }

  /* olx-ui writes its icon colour into the SVG MARKUP — `<svg
     color="var(--color-neutral-130)">` with `<path fill="var(--color-neutral-130)">` — so
     the glyph resolves to the palette's near-black ink (#1A1D23) and disappears on dark.
     No `color` rule reaches an SVG fill and no colour audit sees it (there is no text
     node). Hit list: every search-autocomplete suggestion's magnifier, the ad page's
     "Na OLX desde" calendar and location pin, the identity-validation alert's close X.
     The token canNOT be lifted at the root: the site also uses `--color-neutral-130` as a
     deliberately DARK surface (`.olx-arrow-button` disc, `.olx-media-counter` photo-count
     pill, `.olx-image-carousel__content-overlay`), which a light value would flip white.
     Repaint the fill itself instead. */
  svg[color="var(--color-neutral-130)"],
  path[fill="var(--color-neutral-130)"] {
    fill: #c4cdd6 !important;
    color: #c4cdd6 !important;
  }
  /* …`.olx-icon-action` brightens the same token on hover; keep that lift. */
  .olx-icon-action:hover path[fill="var(--color-neutral-130)"] { fill: #e6edf3 !important; }

  /* olx-ui writes the SAME two ink tokens from a CSS CLASS as well, on SVGs whose
     paths are a plain `fill="currentColor"` — no `color` attribute, no literal hex,
     so every markup hook above is blind to them. The family:
     `.olx-dropdown__chevron-icon { --color: var(--color-neutral-130); color: var(--color) }`
     (every native-select caret — the header category picker on home/search AND the
     profile's Categoria / Localização / Ordenar row), the profile card's
     `> svg { color: var(--color-neutral-130) }` ("Na OLX desde", whose location pin
     on the next line is nested one level deeper and so escaped the same rule and
     rendered fine — two lines of one list, one icon simply absent), the search rail's
     subcategory chevrons, and `.olx-ad-card__location svg { color: var(--color-neutral-120) }`.
     Declaring the two ink tokens ON `svg` lifts the whole family at once and cannot
     lighten the surfaces built from the same token: `.olx-arrow-button`'s disc,
     `.olx-media-counter` / `.olx-ad-media-counter` pill and
     `.olx-image-carousel__content-overlay` are HTML boxes that resolve the token on
     THEMSELVES, and a wrapper indirecting through its own var
     (`.olx-arrow-button { --svg-color: var(--color-neutral-130) }`) substitutes a
     concrete colour where it is DECLARED, so the value that inherits into the glyph
     is no longer a token this can reach. */
  svg {
    --color-neutral-120: #c4cdd6;
    --color-neutral-130: #c4cdd6;
    /* olx-ui's "spot" illustrations (empty states — /cupons' "Não há cupons
       disponíveis", no-results panels) draw a ~100px disc behind the artwork from
       `--spots-background-neutral`, a literal #fff, so the page carries a bright
       white circle no element-bg audit can see. This is the ACHROMATIC variant of
       the family: its artwork is only `--spots-color-neutral` (#cfd4dd) and
       `--spots-border-color-neutral` (#8994a9), both of which stay legible once the
       disc goes dark — unlike the FeaturedBrands raster tiles, there is no baked
       dark ink to erase. The COLOURED spots (the ad page's lavender location
       building, the account-level spot) paint from their own `--spots-*` tokens and
       keep their hues. Declared on `svg` so it can never reach an HTML surface. */
    --spots-background-neutral: #21262d;
  }
  /* The `svg` scope above only reaches glyphs whose colour rule is written AGAINST the
     SVG. Icon-only CONTROLS declare `color: var(--color-neutral-1x0)` on the button and
     let a `fill="currentColor"` child inherit it — the token is then substituted on the
     BUTTON, out of the svg rule's reach, and the glyph is near-black again. Two shipped
     that way and are visible only at narrow viewports: the category strip's
     `.olx-tabs__scroll-button` arrows (1.1:1) and the mobile home's location button
     (1.8:1). This is the complete set of olx-ui controls that pair an icon with an
     own-element `color` off the near-black end of the neutral scale; every SURFACE use
     of the same tokens (`.olx-arrow-button`, `.olx-media-counter`, `.bg-neutral-1x0`,
     `.olx-header__overlay`, `.olx-tooltip__floating--secondary`) declares it for its own
     `background` and is deliberately left out. */
  .olx-tabs__scroll-button,
  .olx-tabs__tablist-button,
  .olx-header__icon-button,
  .olx-navbar__link,
  .olx-tooltip__close-button,
  .olx-core-input-password,
  .olx-text-input__button-password,
  .olx-breadcrumb__unlabeled-link,
  .olx-multiselect__check-button,
  .olx-help-text,
  .olx-ad-card__labels-item > span,
  .olx-static-footer__social-link,
  .olx-old-static-footer__social-link,
  [class*="home-location__button"] {
    --color-neutral-120: #c4cdd6;
    --color-neutral-130: #c4cdd6;
  }

  /* Scopes that deliberately run a BRIGHTER ink than the icon default must restate it
     at the glyph — the `svg` declaration above shadows a wrapper-level remap. */
  .olx-badge svg,
  .olx-core-badge svg,
  .olx-alertbox svg,
  [class*="alertbox"] svg,
  .olx-icon-action:hover svg {
    --color-neutral-130: #e6edf3;
  }
  /* …and the tooltip PIN is the one SVG in the site that must keep the DARK end of the
     scale: the tooltip is natively a dark chip already (`bg-neutral-120` #3C4453 with
     #EFF1F5 copy, so the theme leaves it alone), and its pointer is a Tailwind
     `fill-neutral-120` triangle meant to read as the chip's own corner. The `svg` remap
     above lifts that token to the icon ink, so the pointer rendered as a bright #c4cdd6
     wedge hanging off a dark chip — visible only while a tooltip is open, e.g. the ad
     page's "Solicite ao vendedor a ativação do pagamento online" bubble over the mobile
     price bar. Put the surface value back on the pin. `--color-neutral-130` is listed
     too: the BEM `olx-tooltip__floating--secondary` variant draws its chip from that
     token instead. */
  .tooltip-pin,
  [class*="tooltip"] svg[class*="fill-neutral-"] {
    --color-neutral-120: #3c4453;
    --color-neutral-130: #1a1d23;
  }

  /* The ad view redefines `--color-primary-100` from the OLX orange to the brand
     purple on `body`, so the price box's "Simular empréstimo" glyph paints #6E0AD6
     (2.3:1) beside a link LABEL the purple lift has already brightened to #b794f6 —
     the icon reads as a smudge next to legible copy. Lift the glyph to the same
     violet. The hook stays inside `#adview`, the only scope where that token is the
     purple rather than the orange, so orange icons elsewhere keep their hue. */
  #adview svg[color="var(--color-primary-100)"],
  #adview path[fill="var(--color-primary-100)"] {
    fill: #b794f6 !important;
    color: #b794f6 !important;
  }
  /* The listing page's transactional-seller rating star is
     `fill="var(--color-primary-100)"`, and OUTSIDE `#adview` that token is the OLX
     ORANGE — the site paints this star the same amber it paints a Google review star
     two cards down. A flat violet here is a hue swap, not a lift: it makes the rating
     read as brand chrome and matches nothing else on the card. Keep it in the amber
     family. Both scanners are blind to this (native and themed are each chromatic, so
     `audit-chroma` sees no flattening, and an SVG fill carries no text node). Its
     CSS-modules class is hashed on BOTH sides of the name, so match the stable middle
     rather than the churning build hash. */
  [class*="__transactionalSellerStar"],
  [class*="__transactionalSellerStar"] path {
    fill: #f2901f !important;
    color: #f2901f !important;
  }

  /* OLX secondary accent is a saturated purple (#6E0AD6) that fails
     contrast on dark — lift to a lighter, readable violet, same hue. */
  .text-secondary-100, .text-secondary-110, .text-secondary-90,
  .olx-link--secondary, .olx-core-link--secondary {
    color: #b794f6 !important;
  }

  /* olx-link (distinct from olx-core-link) — default dark text and the
     purple secondary variant; both unreadable on dark. */
  .olx-link, .olx-link--small, .olx-link--caption, .olx-link--main {
    color: #c4cdd6 !important;
  }
  .olx-link--secondary, a.olx-link[class*="secondary"] { color: #b794f6 !important; }

  /* ------------------------------------------------------------
     The "--main" link variant is the worst dark-on-dark offender:
     olx-ui paints it via `color: var(--link-color)` where
     `--link-color` resolves to the raw saturated OLX purple
     (#6E0AD6, luminance ~0.04). A bare `.olx-link--main`/
     `.olx-core-link--main { color: ... !important }` TIES that
     class on specificity and loses on cascade order, so the purple
     survives. Re-scope the override from the stable section IDs (#header
     the global nav/skip-links, #adview the ad body) to raise specificity
     and WIN — lifting the purple action links (Simular empréstimo, Exibir
     telefone, the skip-links, breadcrumb home, "Ver descrição completa")
     to a readable lifted violet of the same hue. The generic `.olx-core-link
     --main` fallback further down covers the rest of the page. NOTE: this
     block also carried `#root` selectors; the Next.js App Router rewrite
     dropped that wrapper, so they matched nothing and were removed.
     `#layout-default-profile` is the /perfil/ app's shell: its one body-level
     `--main` link ("Exibir todas as avaliações") was falling through to the
     generic fallback and rendering as plain near-white body copy — no link
     affordance at all, and visibly out of step with the violet header links
     right above it. Its ad-card titles do NOT carry `--main`, so scoping the
     lift to the shell reaches that action link and nothing else. */
  #header .olx-link--main,
  #header .olx-core-link--main,
  #adview .olx-link--main,
  #adview .olx-core-link--main,
  #layout-default-profile .olx-link--main,
  #layout-default-profile .olx-core-link--main {
    color: #b794f6 !important;
    -webkit-text-fill-color: #b794f6 !important;
  }
  #header .olx-link--main:hover,
  #header .olx-core-link--main:hover,
  #adview .olx-link--main:hover,
  #adview .olx-core-link--main:hover,
  #layout-default-profile .olx-link--main:hover,
  #layout-default-profile .olx-core-link--main:hover {
    color: #d2bdff !important;
    -webkit-text-fill-color: #d2bdff !important;
  }

  /* olx-chip — the narrow-viewport filter pills ("Filtros", "Mais recentes") on the
     seller profile and the listing filter rail. Every one of its five states paints
     from the LIGHT end of the scales: default `--color-neutral-70` (#FFF) on a
     `--color-neutral-90` ring, checked `--color-secondary-70` (#F0E6FF) on
     `--color-secondary-130`, disabled `--color-neutral-80`. Desktop routes the same
     controls through `olx-core-singleselect`, so the chips only ever render at narrow
     widths and a desktop pass never sees the white pills. Remap the scales on the
     content element so all five states keep their relative meaning: neutral default,
     brighter ring on hover, violet when checked, recessed when disabled. */
  .olx-chip,
  .olx-chip__content {
    --color-neutral-70: #21262d;
    --color-neutral-80: #1c2128;
    --color-neutral-90: #30363d;
    --color-neutral-100: #6b7681;
    --color-neutral-130: #c4cdd6;
    --color-secondary-70: #2a2440;
    --color-secondary-130: #c9b6f5;
  }

  /* Tabs (home "Categorias / Tudo" nav + olx-tabs labels) — dark and
     purple-selected labels lifted to the readable scale / accent. */
  [class*="tabs-navigation__tab"],
  .olx-tabs__tab-label,
  .olx-tabs__tab { color: #9aa6b0 !important; }
  [class*="tabs-navigation__tab"][aria-selected="true"],
  [class*="tabs-navigation__tab--active"],
  .olx-tabs__tab--active .olx-tabs__tab-label,
  .olx-tabs__tab[aria-selected="true"] .olx-tabs__tab-label {
    color: #f6b35e !important;
  }
  /* The selected tab also marks itself with a coloured bottom BORDER while the
     unselected ones leave theirs transparent — and the blanket `* { border-color }`
     reset at the top of the file painted ALL of them the same grey hairline, so the
     footer tab strip lost its "you are here" underline. Restore the pair (the
     accent matches the selected label above). */
  .olx-tabs__tab { border-bottom-color: transparent !important; }
  /* The component also answers the pointer: `:hover` repaints both the label and that
     bottom border to `--tab-font-color-hover` / `--tab-border-color-hover` (both the
     OLX purple). Our `color` and `border-bottom-color` pins above are `!important` with
     no hover counterpart, so the SEO footer's tab strip lost every trace of feedback —
     an unselected tab looked identical whether or not the pointer was on it. Give the
     cue back on the dark palette. The `--active` rules that follow restate `:hover` so
     they still tie-break above these (0-2-0 / 0-3-0) and the selected tab keeps its
     amber marker under the pointer. */
  .olx-tabs__tab:hover { border-bottom-color: #6b7681 !important; }
  .olx-tabs__tab:hover,
  .olx-tabs__tab:hover .olx-tabs__tab-label { color: #e6edf3 !important; }
  .olx-tabs__tab--active,
  .olx-tabs__tab--active:hover,
  .olx-tabs__tab[aria-selected="true"] { border-bottom-color: #f6b35e !important; }
  .olx-tabs__tab--active:hover .olx-tabs__tab-label,
  .olx-tabs__tab[aria-selected="true"]:hover .olx-tabs__tab-label { color: #f6b35e !important; }
  /* An overflowing tab strip gets a scroll-fade at each end, painted as a
     `background-IMAGE` gradient running to `--color-neutral-70` (#FFF). A
     background-COLOR override can never reach it, so a white smear survives at
     the edges of the strip. */
  /* olx-ui ships the same widget under a SECOND name, `.olx-tabs__scroll-button`, and
     that is the one the narrow-viewport home renders on its "Pesquisas Populares"
     strip — a 36px block of literal white with a `--tab-font-color-default` (#1A1D23)
     chevron on it, i.e. a white pad carrying an invisible caret. Desktop never shows
     it, so a desktop-only pass reads clean. Its glyph comes off the TAB token family,
     not the neutral scale, so the icon rules above cannot reach it either. */
  .olx-tabs__tablist-button--left,
  .olx-tabs__tablist-button--right,
  .olx-tabs__scroll-button,
  .olx-tabs__scroll-button--left,
  .olx-tabs__scroll-button--right {
    background-image: none !important;
    background-color: transparent !important;
  }
  .olx-tabs__scroll-button,
  .olx-tabs__tablist-button {
    --tab-font-color-default: #c4cdd6;
    --tab-font-color-hover: #e6edf3;
    --tab-font-color-pressed: #e6edf3;
  }

  /* Keep semantic feedback colors readable on dark */
  [class*="text-feedback-success"] { color: #6fd6a8 !important; }
  [class*="text-feedback-error"], [class*="text-feedback-danger"] { color: #f0a193 !important; }
  [class*="text-feedback-warning"] { color: #e6c463 !important; }

  /* ============================================================
     Third-party consent / CMP dialog. OLX uses Google Funding
     Choices (.fc-consent-root), whose stylesheet is injected AFTER
     our theme — so a bare `.fc-dialog` rule TIES on specificity and
     LOSES on source order, leaving a blinding white sheet on first
     visit. Scope every rule from `.fc-consent-root` to out-specify
     the CMP and dark the whole sheet + lift its dark Material text.
     ============================================================ */
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-content,
  .fc-consent-root .fc-choice-dialog,
  .fc-consent-root .fc-header,
  .fc-consent-root .fc-footer,
  [class*="adopt-"][class*="dialog"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-dialog h1,
  .fc-consent-root .fc-dialog h2,
  .fc-consent-root .fc-dialog p,
  .fc-consent-root .fc-dialog li,
  .fc-consent-root .fc-dialog span,
  .fc-consent-root .fc-dialog div,
  .fc-consent-root .fc-dialog-headline,
  .fc-consent-root .fc-dialog-content {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* …but FC's text ACTIONS are links, not copy: "Manage options", each purpose's
     "View details" and "List of partners" are painted its Material blue (#1967D2).
     The blanket text rule above swallowed them (`-webkit-text-fill-color` inherits,
     so even the anchors it never matched still rendered white), leaving the
     dialog's third action looking like a heading rather than something clickable.
     Give them back a link colour, lifted for the dark sheet. "Manage options" is a
     <p>, so it needs the tag qualifier to out-specify the `.fc-dialog p` rule above
     rather than tie it and lose. */
  .fc-consent-root .fc-dialog a,
  .fc-consent-root .fc-purpose-feature-more-info,
  .fc-consent-root .fc-dialog p.fc-manage-options-third-button-label {
    color: #79a8f0 !important;
    -webkit-text-fill-color: #79a8f0 !important;
  }
  /* Logo tile + FAQ panel keep a literal white bg. The "Learn more" chevron
     disc is painted by FC's own `.fc-consent-root .fc-faq-header .fc-faq-icon`
     (0-3-0, !important), which out-specifies a two-class rule — so it stayed a
     white disc with a light hairline. Match it from the dialog to win. */
  .fc-consent-root .fc-faq-icon,
  .fc-consent-root .fc-faq-contents {
    background-color: #14181d !important;
  }
  .fc-consent-root .fc-dialog .fc-faq-header .fc-faq-icon {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-dialog hr,
  .fc-consent-root .fc-dialog [class*="divider"] {
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }
  /* "Manage options" preferences panel: the sticky header bar, each
     per-purpose card (.fc-preference-container) and the manage-vendors
     row all ship a literal white surface with a light hairline — our
     lifted near-white text ghosts onto them. Settle them onto an
     elevated dark surface so the copy + toggles read. */
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-preference-container,
  .fc-consent-root .fc-navigation-button,
  .fc-consent-root .fc-manage-vendors,
  .fc-consent-root [class*="preferences-container"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-preference-container {
    background-color: #21262d !important;
  }
  /* Same specificity trap as the FAQ icon: FC paints the "Vendor preferences"
     row from `.fc-consent-root .fc-data-preferences-dialog .fc-navigation-button`
     (0-3-0, !important), so our 0-2-0 rule lost and it stayed a white bar with
     our lifted near-white label ghosting on it. It is 39px tall, so the audit's
     height floor skips it too. Match from the navigation wrapper to win. */
  .fc-consent-root .fc-data-preferences-dialog .fc-navigation .fc-navigation-button {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* AdOpt (`#adopt-*` / #cookie-banner) is a SECOND consent CMP the site now serves
     alongside Funding Choices — it renders its own dark palette off `color-scheme:
     dark` (banner #3C4453), so most of it needs no theming and the blanket
     `* { border-color }` reset already softens its accept/reject buttons. But its
     outline "Minhas opções" button rings itself white from `.adopt-c-* { border-color:
     #fff !important }` (0-1-0), which the `*` reset can't beat — a glaring white pill on
     the dark banner. The stable `#adopt-preferences-button` id (1-0-0) wins; settle the
     ring onto a readable grey so it still reads as an outline secondary action. */
  #adopt-preferences-button {
    border-color: #6b7681 !important;
  }

  /* ============================================================
     Alert / notification boxes (olx-alertbox)
     ------------------------------------------------------------
     The component resolves its surface, copy and icon from
     `--background-color` / `--color` / `--svg-color`, which the base
     class aliases onto the neutral scale and each variant onto a
     feedback scale. Its real variants are `--success`, `--error`,
     `--attention` and `--information`: a blanket `[class*="alertbox"]`
     background flattened attention (amber) and information (cyan) to
     the same neutral grey, and a blanket copy colour erased the tinted
     text the site sets on their spans. Remap the scales on the box
     instead, so the base goes elevated-dark and every variant keeps
     its meaning. (Rules named `--warning` / `--danger` matched nothing
     — those variants do not exist in olx-ui.)
     ============================================================ */
  .olx-alertbox,
  [class*="alertbox"] {
    --color-neutral-80: #1c2128;
    --color-neutral-120: #c4cdd6;
    --color-neutral-130: #e6edf3;
    --color-feedback-success-80: #102a23;
    --color-feedback-success-100: #6fd6a8;
    --color-feedback-success-110: #6fd6a8;
    --color-feedback-attention-80: #322a12;
    --color-feedback-attention-100: #e6c463;
    --color-feedback-attention-110: #e6c463;
    --color-feedback-error-80: #3a1b16;
    --color-feedback-error-100: #f0a193;
    --color-feedback-error-110: #f0a193;
    --color-feedback-info-80: #10303a;
    --color-feedback-info-100: #9ce6f9;
    --color-feedback-info-110: #9ce6f9;
    border-color: #2d333b !important;
  }

  /* In-flow / pre-rendered dialog body copy (olx-text) carries a
     near-black color that becomes dark-on-dark once a modal opens. */
  .olx-modal__content .olx-text,
  [class*="modal__content"] .olx-text,
  .olx-modal__dialog .olx-text { color: #c4cdd6 !important; }

  /* ============================================================
     Modals (favourite, share, report, consent, delivery)
     ============================================================ */
  .olx-modal__dialog,
  .olx-modal__content,
  [class*="modal__dialog"],
  [class*="modal__content"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* `[data-ds-component="DS-Modal"]` marks the full-viewport fixed SCRIM
     (`div.olx-modal`, natively `rgba(0,0,0,.333)`), never the card — the card is
     `__dialog` / `__content` above. Painting it with the elevated surface filled the
     whole viewport with the same tone as the dialog, so every BEM modal (share,
     report, login prompt) lost both its backdrop dimming and its own card edge: the
     sheet read as a blank page with floating controls. Keep it a scrim. */
  .olx-modal__overlay,
  [data-ds-component="DS-Modal"],
  [class*="modal__overlay"],
  [class*="backdrop"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  /* Every BEM modal (share, report, delivery, favourite prompt) closes through
     `.olx-modal__close-button`, whose X is `fill="currentColor"` over the
     component's near-black `color` (#1A1D23) — on the now-dark dialog the
     control all but disappears. Distinct from `.olx-modal-close` (the newer
     single-dash side-sheet close, handled below). */
  .olx-modal__close-button { color: #e6edf3 !important; }
  /* Both close controls fill their disc on hover from a light token
     (`--modal-button-background-color-hover` / `--modal-close-button-hover-background-color`,
     both #CFD4DD), which the ink-only rules cannot reach: the disc went bright and
     swallowed the white X. Match `.olx-modal-close:hover` below. */
  .olx-modal__close-button:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }
  /* A THIRD close-control name — `olx-modal-close-button`, single-dash but with the
     `-button` suffix, so neither `.olx-modal__close-button` nor `.olx-modal-close`
     matches it (class selectors match whole tokens). It is the only way out of the
     /cupons "Categorias" filter dialog, and its `fill="currentColor"` X inherits the
     component's #3C4453 — 1.7:1 on the dark panel, effectively invisible. */
  .olx-modal-close-button { color: #e6edf3 !important; }
  .olx-modal-close-button:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* The header "Categorias" side-sheet uses the newer single-dash component
     names (olx-modal-content / -header / -body), which the BEM rules above
     don't reach. Every category row is an `olx-core-accordion` on a literal
     white (#FFF, expanded #EFF1F5) surface — our lifted near-white labels then
     read white-on-white — and the close button is a white disc holding a white
     icon. Dark the sheet, its rows and the close control. */
  .olx-modal-content,
  .olx-modal-header,
  .olx-modal-body {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .olx-core-accordion {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .olx-core-accordion:hover { background-color: #21262d !important; }
  .olx-core-accordion__header,
  .olx-core-accordion__content,
  .olx-core-accordion__header * { color: #e6edf3 !important; }
  .olx-modal-close {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  .olx-modal-close:hover { background-color: #2d333b !important; }
  /* Sheet lists mark the CURRENT choice with a tick drawn straight from the raw brand
     purple — `<svg color="var(--color-secondary-100)">` with a `fill` of the same token
     (the mobile header's Localização sheet, whose "Todos os estados" tick is the only
     thing distinguishing the selected row). At #6E0AD6 that is ~2.2:1 on the dark sheet,
     so the selection signal all but disappears. Lift the markup hook itself rather than
     the token: `--color-secondary-100` is also the ad page's seller-medal outline and
     the `--spots-*` illustration hues, which must keep their values, and the modal scope
     reaches none of those. */
  .olx-modal-body svg[color="var(--color-secondary-100)"],
  .olx-modal-body path[fill="var(--color-secondary-100)"] {
    fill: #b794f6 !important;
    color: #b794f6 !important;
  }

  /* ============================================================
     Home "Produtos / Tipo de imóveis mais buscados" carousel
     ------------------------------------------------------------
     Each card is an `<a>` whose only surface rule paints the literal
     `--color-neutral-70` white — no shared card class reaches it, so the
     whole strip stays white on the dark home page and the product name
     (`text-neutral-130`, lifted to near-white by the ink rules) renders
     white-on-white. The product artwork is transparent-cutout webp, so a
     dark card leaves it intact. Two selector forms because olx-ui migrates
     module class names between `Component_element__hash` and
     `Component-module-scss-module__hash__element` component by component.
     ============================================================ */
  [class*="most-searched-item__card"],
  [class*="MostSearchedItem"][class*="card"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
  }

  /* ============================================================
     Filter option side-sheet (Marca / Modelo "Todas as marcas")
     ------------------------------------------------------------
     Two literal-light surfaces inside an otherwise dark side sheet:
     the STICKY search band (`inputContent`, `--color-neutral-70` = #FFF)
     and the ROW HOVER (`itemWrapper a:hover`, `--color-neutral-80`), whose
     label is near-white here, so the hovered brand becomes unreadable.
     ============================================================ */
  [class*="FilterOptionsModal"][class*="inputContent"] {
    background-color: #1c2128 !important;
  }
  [class*="FilterOptionsModal"][class*="itemWrapper"] a:hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* ============================================================
     Photo-lightbox safety-tip slide
     ------------------------------------------------------------
     The last slide of the ad gallery lightbox is a "#dica-de-segurança"
     panel: two nested literal-white DS-Flex boxes filling the whole stage.
     Their classes are churning styled-components hashes, so anchor on the
     stable BEM wrapper plus the `data-ds-component` contract.
     ============================================================ */
  .advc-slide-show__wrap-security-tip > [data-ds-component="DS-Flex"],
  .advc-slide-show__wrap-security-tip > [data-ds-component="DS-Flex"] > [data-ds-component="DS-Flex"] {
    background-color: #14181d !important;
  }

  /* ============================================================
     Seller "Nível de cadastro" meter medal
     ------------------------------------------------------------
     The end-cap medal is a two-path SVG: an inner shape and an outline.
     In the NOT-YET-REACHED state the site fills the inner shape with an
     inline literal white, which is invisible on the native white card but
     renders a solid white disc — the brightest object on the page — once
     the card is dark. Dropping the fill reproduces the native outline-only
     ribbon. The REACHED state fills that path with a brand colour instead,
     so keying on the literal white leaves it untouched.
     ============================================================ */
  /* The two apps write that white two different ways — the ad view as an inline
     `style`, the /perfil/ app as a `fill` markup attribute — so both forms are needed
     or the profile keeps a solid white disc. */
  #reputation-bar svg path[style*="fill: rgb(255, 255, 255)"],
  #reputation-bar svg path[fill="#FFFFFF"] {
    fill: none !important;
  }
  /* Dropping the body leaves the OUTLINE path as the whole medal, and that path is
     `fill="#CFD4DD"` — the same literal the empty-star rule darkens to the unfilled
     tone, which erases the ribbon entirely. It is a shape, not a rating star: restate a
     legible grey here (id + attribute + type out-ranks the shell-scoped star rule). */
  #reputation-bar svg path[fill="#CFD4DD"] {
    fill: #8b949e !important;
  }

  /* ============================================================
     Listing-rail breadcrumb
     ------------------------------------------------------------
     Each crumb is an `<a>` wrapping a `<p class="…colorSecondary">` that
     the site paints the raw action purple; the paragraph's own colour wins
     over the anchor's, so the muted-text rules flattened every crumb to
     plain grey and the rail lost its only link affordance. Lift to the same
     violet the header/ad-view action links use.
     ============================================================ */
  [class*="CategoryLink"][class*="colorSecondary"] {
    color: #b794f6 !important;
    -webkit-text-fill-color: #b794f6 !important;
  }

  /* ============================================================
     Dividers
     ============================================================ */
  hr, .olx-divider, [data-ds-component="DS-Divider"] {
    border-color: #2d333b !important;
    background-color: #2d333b !important;
  }

  /* ============================================================
     Generic links
     ============================================================ */
  a { color: #c4cdd6; }
  a:hover { color: #ffffff !important; }
  .olx-core-link--main { color: #e6edf3 !important; }
  .olx-core-link--grey { color: #9aa6b0 !important; }

  /* ============================================================
     Footer
     ============================================================ */
  footer,
  .olx-footer,
  [data-ds-component="DS-Footer"],
  [class*="footer"] {
    background-color: #0d1117 !important;
    color: #9aa6b0 !important;
    border-top: 1px solid #2d333b !important;
  }
  footer a,
  .olx-footer a,
  [data-ds-component="DS-Footer-Link"] { color: #9aa6b0 !important; }
  footer a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Taboola sponsored-content widget (trc_* / videoCube) at the foot of
     the search results renders bright-white video tiles with black
     titles. Dark the tiles, drop the white hover-fade overlay, and
     lift the labels so the unit blends into the dark page.
     ============================================================ */
  [id^="internal_trc"], [id*="taboola"],
  .trc_rbox, .trc_rbox_outer, .videoCube, .trc_spotlight_item,
  .trc_popover, .trc_popover_fade {
    background-color: #1c2128 !important;
  }
  .trc_exclude_overlay { background-color: transparent !important; }
  /* The popover's own heading strip is a CHILD element carrying its own
     literal #F7F7F7, so darkening `.trc_popover` alone leaves a white band
     across the top of the panel with the lifted label invisible on it. */
  .trc_popover_title_wrapper { background-color: #1c2128 !important; }
  .videoCube .video-title, .videoCube .video-label,
  .trc_spotlight_item .video-title, .trc-main-label,
  .trc_spotlight_item .trc-main-label *,
  .trc_popover, .trc_popover * { color: #c4cdd6 !important; }

  /* ============================================================
     Scrollbar polish
     ------------------------------------------------------------
     The COLOURS carry `!important` because olx-ui styles its own panel
     scrollbars from a nested `&::-webkit-scrollbar-thumb { background-color:
     var(--color-neutral-90) }` (#CFD4DD) inside the component class — that
     compiles to a 0-1-1 selector, so these unscoped 0-0-0 rules tie nothing
     and lose, leaving a bright light-grey thumb down the search-autocomplete
     panel, the Categorias side-sheet body, every open singleselect menu and
     the mobile Filtros sheet. `!important` wins regardless of specificity.
     The thumb is #484f58 rather than the hairline tone: a #2d333b thumb is
     invisible against the #1c2128 those panels are painted, so the scroll
     position would be lost. WIDTH stays non-important on purpose — the site
     draws a narrower bar inside its panels and that geometry is fine.
     ============================================================ */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #0d1117 !important; }
  ::-webkit-scrollbar-thumb { background: #484f58 !important; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #6b7681 !important; }
}

@-moz-document domain("ajuda.olx.com.br") {
[class*="layout__Wrapper"] div,
  [class*="layout__Wrapper"] p,
  [class*="layout__Wrapper"] span,
  [class*="layout__Wrapper"] li,
  [class*="layout__Wrapper"] td,
  [class*="layout__Wrapper"] th,
  [class*="layout__Wrapper"] address,
  [class*="layout__Wrapper"] strong { color: #c4cdd6 !important; }
  [class*="layout__Wrapper"] h1,
  [class*="layout__Wrapper"] h2,
  [class*="layout__Wrapper"] h3,
  [class*="layout__Wrapper"] h4,
  [class*="layout__Wrapper"] [class*="Title"] { color: #e6edf3 !important; }
  /* Article links, breadcrumb crumbs and the FAQ shortcut list are the page's
     only chromatic ink; the marketplace lifts the same brand purple to #b794f6. */
  [class*="layout__Wrapper"] a,
  [class*="layout__Wrapper"] a [class*="Title"] { color: #b794f6 !important; }
  /* The header's slide-in menu is a literal-white 300px panel behind a dark scrim.
     It is in the DOM at every width, parked off-canvas, so it never shows up in a
     desktop screenshot. */
  [class*="SubHeaderWrap"] { background-color: #1c2128 !important; }
  /* The article's "Esse artigo foi útil? Sim / Não" pair is outlined-only — its
     orange border IS the button, and the blanket hairline reset erases it. */
  [class*="iconButton__ButtonStyled"] {
    border-color: #f2901f !important;
    color: #f2901f !important;
  }
  /* The help search field carries no `type` attribute, so the marketplace block's
     `input[type="text"]` rule — an ATTRIBUTE match — never reaches it: the field fell
     through to the UA's own dark form control (#3B3B3B, from `color-scheme: dark`)
     while the app's literal #4A4A4A ink stayed put, at 1.26:1 for anything typed. */
  [class*="search-bar__InputSearch"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  /* The suggestion panel only mounts once a query is typed, so it never appears in a
     load-time scan; it is a literal-white sheet under the lifted purple article links. */
  [class*="WrapperAutoComplete"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    /* Its frame is the same #F7F1FD 4px shadow the search box wears, and a literal
       white `::before` bridges the seam between the two. */
    box-shadow: 0 4px 0 4px #b794f6 !important;
  }
  [class*="WrapperAutoComplete"]::before { background-color: #1c2128 !important; }
  [class*="ItemLink"]:hover { background-color: #21262d !important; }
  /* Both the search box and the category cards signal hover / focus with a 4px
     `box-shadow` in the brand's palest lavender (#F7F1FD) — a soft wash on the white
     page, a hard white ring here. The marketplace lifts the same brand purple to
     #b794f6; carry the ring at the same weight. */
  [class*="search-bar__Wrapper-sc"]:focus-within,
  [class*="category-container__Container"]:hover {
    box-shadow: 0 0 0 4px #b794f6 !important;
  }
  /* "Não encontrou o que procurava? Fale com a gente" is the app's own CTA, outside
     the olx-ui button classes the marketplace block re-inks, so it kept white copy on
     the raw #F28000 (2.7:1). Match the orange CTAs everywhere else. */
  [class*="contact-us__Button"] {
    background-color: #f2901f !important;
    color: #1a1206 !important;
  }
  /* The narrow-width FAQ carousel hides its horizontal scrollbar behind a full-width
     8px `::after` in literal white — invisible on the native page, a bright rule across
     the column here. It only exists below the mobile breakpoint. */
  [class*="faq-slider__HideScroll"]::after { background-color: #14181d !important; }
}

@-moz-document domain("planos.olx.com.br") {
[data-testid="container"] { --color-neutral-80: #1c2128 !important; }
  /* Only the RESTING fill comes from that token; the tile's hover state is a
     literal pair — the brand lavender #F0E6FF fill plus a #6E0AD6 ring — that no
     token remap reaches, and the blanket `* { border-color }` reset erases the
     ring, so the whole hover cue was a white slab under near-white labels. The
     tile carries only per-build styled-components hashes, so hook it by position
     in the grid. Violet chip + lifted ring, matching the selected states in the
     marketplace block. */
  [data-testid="container"] > div:hover {
    background-color: #2a2440 !important;
    border-color: #b794f6 !important;
  }
}

@-moz-document domain("financiamentos.olx.com.br"), domain("feiraoautos.olx.com.br") {
[class^="sc-"],
  [class*=" sc-"] { background-color: transparent !important; }
  /* Each result card is a focusable span wrapping the photo and the price block. */
  span[tabindex="0"] { background-color: #1c2128 !important; }
  /* The hero band is the page's brand surface and carries the white headline; at
     narrow widths its fill is the <header> itself, so the clear-out above drops it
     and the copy lands on the page base. `DEFAULT_THEME` is the app's styled-
     components theme marker and separates it from the filter rail's own headers. */
  header.DEFAULT_THEME { background-color: #6e0ad6 !important; }
  #filter-modal-container { background-color: #1c2128 !important; }
  /* The rail's price and year ranges are `rc-slider`s whose UNFILLED track keeps the
     library's #CFD4DD — a bright 168x5 bar under the audit's size floor. The filled
     portion and the handles paint from the brand orange and stay. */
  .rc-slider-rail { background-color: #3a424c !important; }
  /* "Selecione a marca" opens the brand picker and is the rail's only raw
     brand-purple ink (2:1 here); the marketplace lifts the same purple to
     #b794f6. It is the one styled-components <p> in the rail with no typo-*
     utility on it — every other <p> there is a label or a range read-out.
     Its chevron is the adjacent svg, drawn from currentColor. */
  #filter-modal-container p[class^="sc-"]:not([class*="typo-"]),
  #filter-modal-container p[class^="sc-"]:not([class*="typo-"]) + svg,
  #filter-modal-container p[class^="sc-"]:not([class*="typo-"]) + svg path {
    color: #b794f6 !important;
    fill: #b794f6 !important;
  }
}
